import React from 'react';
import { useAppStore } from '../store/useAppStore';
import { Thermometer, Gauge, Scale, Pipette, Wand2 } from 'lucide-react';
import { formatTemperature, formatPH, formatMass } from '../utils/units';

export function MeasurementHUD() {
  const selectedVesselId = useAppStore(state => state.selectedVesselId);
  const vessels = useAppStore(state => state.vessels);
  const language = useAppStore(state => state.language);
  const activeTool = useAppStore(state => state.activeTool);
  const setActiveTool = useAppStore(state => state.setActiveTool);
  const spills = useAppStore(state => state.spills);
  const activeKinetics = useAppStore(state => state.activeKinetics);
  const spillCount = Object.keys(spills || {}).length;

  const vessel = selectedVesselId ? vessels[selectedVesselId] : null;
  const kinetics = selectedVesselId ? activeKinetics[selectedVesselId] : null;
  const timeWarp = kinetics?.timeWarp;
  const timeWarpRatio = timeWarp ? Math.round(timeWarp.physical_s / (kinetics?.duration || 5.0)) : 1;
  const t = (en: string, vi: string) => language === 'en' ? en : vi;

  const temp = vessel ? vessel.temperature_c : 25.0;
  const ph = vessel ? vessel.ph : 7.0;
  const tare = vessel ? (vessel.tare_g ?? (vessel.type === 'test_tube' ? 25.0 : vessel.type === 'flask' ? 95.0 : 85.0)) : 0.0;
  const netMass = vessel ? (vessel.mass_g ?? ((vessel.volume_ml || 0) * (vessel.density_g_ml || 1.0))) : 0.0;
  const mass = vessel ? netMass + tare : 0.0;

  return (
    <div className="flex items-center gap-2 bg-white/90 backdrop-blur-md px-3 py-1.5 rounded-lg border border-slate-200/80 shadow-md">
      {/* Interactive Pipette / Dropper */}
      <button 
        onClick={() => setActiveTool(activeTool === 'pipette' ? 'none' : 'pipette')}
        className={`flex items-center gap-1.5 px-2.5 py-1 rounded text-xs font-semibold transition-colors ${
          activeTool === 'pipette' ? 'bg-amber-500 text-white shadow-sm' : 'bg-slate-100 hover:bg-slate-200 text-slate-700'
        }`}
        title={t('Pipette / Dropper (Squeeze to draw/dispense)', 'Ống hút nhỏ giọt (Bóp để hút/nhỏ)')}
      >
        <Pipette size={14} />
        <span>{t('Pipette', 'Ống hút')}</span>
      </button>

      {/* Interactive Glass Stirring Rod */}
      <button 
        onClick={() => setActiveTool(activeTool === 'stirring_rod' ? 'none' : 'stirring_rod')}
        className={`flex items-center gap-1.5 px-2.5 py-1 rounded text-xs font-semibold transition-colors ${
          activeTool === 'stirring_rod' ? 'bg-cyan-600 text-white shadow-sm' : 'bg-slate-100 hover:bg-slate-200 text-slate-700'
        }`}
        title={t('Glass Stirring Rod (Move in circle to stir)', 'Đũa thủy tinh (Khuấy vòng tròn)')}
      >
        <Wand2 size={14} />
        <span>{t('Stir Rod', 'Đũa khuấy')}</span>
      </button>

      {/* Interactive Solid Spatula */}
      <button 
        onClick={() => setActiveTool(activeTool === 'spatula' ? 'none' : 'spatula')}
        className={`flex items-center gap-1.5 px-2.5 py-1 rounded text-xs font-semibold transition-colors ${
          activeTool === 'spatula' ? 'bg-violet-600 text-white shadow-sm' : 'bg-slate-100 hover:bg-slate-200 text-slate-700'
        }`}
        title={t('Micro-Spatula (Scoop & transfer solid powder/crystals)', 'Muỗng thìa xúc hóa chất rắn')}
      >
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <path d="M18 2l4 4-14 14H4v-4L18 2z" />
          <path d="M14 6l4 4" />
        </svg>
        <span>{t('Spatula', 'Thìa xúc')}</span>
      </button>

      {/* Interactive Sponge / Cleaning Wiper */}
      <button 
        onClick={() => setActiveTool(activeTool === 'sponge' ? 'none' : 'sponge')}
        className={`flex items-center gap-1.5 px-2.5 py-1 rounded text-xs font-semibold transition-colors ${
          activeTool === 'sponge' ? 'bg-amber-600 text-white shadow-sm ring-2 ring-amber-300' : 'bg-slate-100 hover:bg-slate-200 text-slate-700'
        }`}
        title={t('Lab Cleaning Sponge (Wipe chemical spills & acid stains)', 'Khăn lau phòng thí nghiệm (Lau sạch vết đổ & axit trên bàn)')}
      >
        <span className="text-xs">🧽</span>
        <span>{t('Sponge', 'Khăn lau')}</span>
        {spillCount > 0 && (
          <span className="px-1.5 py-0.2 bg-rose-500 text-white text-[9px] font-bold rounded-full">
            {spillCount}
          </span>
        )}
      </button>

      {/* Thermometer Tool */}
      <button 
        onClick={() => setActiveTool(activeTool === 'thermometer' ? 'none' : 'thermometer')}
        className={`flex items-center gap-1.5 px-2.5 py-1 rounded text-xs font-semibold transition-colors ${
          activeTool === 'thermometer' ? 'bg-red-500 text-white shadow-sm' : 'bg-slate-100 hover:bg-slate-200 text-slate-700'
        }`}
        title={t('Digital Thermometer', 'Nhiệt kế điện tử')}
      >
        <Thermometer size={14} className={temp > 50 ? 'text-red-300 animate-pulse' : ''} />
        <span>{formatTemperature(temp, 'C')}</span>
      </button>

      {/* pH Meter Tool */}
      <button 
        onClick={() => setActiveTool(activeTool === 'ph_meter' ? 'none' : 'ph_meter')}
        className={`flex items-center gap-1.5 px-2.5 py-1 rounded text-xs font-semibold transition-colors ${
          activeTool === 'ph_meter' ? 'bg-indigo-600 text-white shadow-sm' : 'bg-slate-100 hover:bg-slate-200 text-slate-700'
        }`}
        title={t('Digital pH Meter', 'Máy đo pH')}
      >
        <Gauge size={14} />
        <span>pH {formatPH(ph)}</span>
        <span 
          className="w-2 h-2 rounded-full border border-white/50" 
          style={{ backgroundColor: ph < 6 ? '#ef4444' : (ph > 8 ? '#3b82f6' : '#22c55e') }} 
        />
      </button>

      {/* Analytical Balance Tool */}
      <button 
        onClick={() => setActiveTool(activeTool === 'balance' ? 'none' : 'balance')}
        className={`flex items-center gap-1.5 px-2.5 py-1 rounded text-xs font-semibold transition-colors ${
          activeTool === 'balance' ? 'bg-emerald-600 text-white shadow-sm' : 'bg-slate-100 hover:bg-slate-200 text-slate-700'
        }`}
        title={t('Analytical Balance', 'Cân phân tích')}
      >
        <Scale size={14} />
        <span>{formatMass(mass, 'g')}</span>
      </button>

      {/* Time-Honesty Badge (Fix F9): Time-lapse compression indicator */}
      {kinetics && timeWarp && timeWarpRatio >= 2 && (
        <div 
          className="flex items-center gap-1 px-2.5 py-1 rounded text-xs font-bold bg-amber-500/15 border border-amber-500/40 text-amber-700 dark:text-amber-300 shadow-sm animate-pulse select-none"
          title={language === 'en' 
            ? (timeWarp.note_en || `Physical reaction time: ${Math.round(timeWarp.physical_s)}s (~${Math.round(timeWarp.physical_s / 60)} min), displayed in ${Math.round(kinetics.duration || 5)}s`)
            : (timeWarp.note_vi || `Thời gian phản ứng thực: ${Math.round(timeWarp.physical_s)}s (~${Math.round(timeWarp.physical_s / 60)} phút), hiển thị trong ${Math.round(kinetics.duration || 5)}s`)}
        >
          <span>⏩</span>
          <span>{t(`time-lapse ×${timeWarpRatio}`, `tua nhanh ×${timeWarpRatio}`)}</span>
        </div>
      )}
    </div>
  );
}

components\\ReactionLibraryPanel.tsx:
import React, { useEffect, useMemo, useState } from 'react';

type ReactionEntry = {
  id: string;
  title_vi: string;
  topic_vi: string;
  equation: string;
  runtime: string;
  protocolStatus: string;
  observation_vi: string;
  explanation_vi: string;
  safety_vi: string;
  quantityPolicy: string;
  conditions: { description_vi?: string; minTemp_c?: number; catalyst?: string; medium?: string };
  steps: { order: number; instruction_vi: string; checkpoint: string }[];
  effects: { timeWarp?: { physical_s: number; note_vi?: string }; duration_s?: number; after?: {
    precipitate?: { substance: string; color: string; morphology: string };
    gasesOffgassed?: { species: string }[];
  } | null };
};

export default function ReactionLibraryPanel() {
  const [entries, setEntries] = useState<ReactionEntry[]>([]);
  const [error, setError] = useState(false);
  const [query, setQuery] = useState('');
  const [topic, setTopic] = useState('all');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [step, setStep] = useState(0);

  useEffect(() => {
    let mounted = true;
    import('../data/curriculum/reactions.vi.json').then(module => {
      if (mounted) setEntries(module.default.reactions as ReactionEntry[]);
    }).catch(() => { if (mounted) setError(true); });
    return () => { mounted = false; };
  }, []);

  const topics = useMemo(() => [...new Set(entries.map(entry => entry.topic_vi))], [entries]);
  const matches = useMemo(() => {
    const normalized = query.toLocaleLowerCase('vi').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd');
    return entries.filter(entry => {
      const text = `${entry.title_vi} ${entry.equation} ${entry.observation_vi} ${entry.topic_vi}`
        .toLocaleLowerCase('vi').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd');
      return (topic === 'all' || entry.topic_vi === topic) && text.includes(normalized);
    });
  }, [entries, query, topic]);
  const selected = entries.find(entry => entry.id === selectedId);

  return <section className="space-y-3 rounded-xl border border-teal-200 bg-teal-50 p-3 text-xs">
    <h3 className="font-bold text-teal-900">Thư viện phản ứng THPT · {entries.length || '…'} mục</h3>
    <p className="text-teal-800">Các bước định tính, hiện tượng và điều kiện. Mục mở rộng được phân biệt với chương trình mô phỏng đã có.</p>
    {error && <p role="alert">Không tải được dữ liệu. Hãy mở lại bảng hướng dẫn để thử lại.</p>}
    {!selected ? <>
      <input aria-label="Tìm phản ứng" value={query} onChange={event => setQuery(event.target.value)}
        placeholder="Tìm công thức, hiện tượng, chủ đề…" className="w-full rounded border p-2 bg-white" />
      <select aria-label="Lọc chủ đề" value={topic} onChange={event => setTopic(event.target.value)} className="w-full rounded border p-2 bg-white">
        <option value="all">Tất cả chủ đề ({matches.length})</option>
        {topics.map(value => <option key={value} value={value}>{value}</option>)}
      </select>
      <div className="max-h-80 overflow-y-auto space-y-1">
        {matches.map(entry => <button key={entry.id} onClick={() => { setSelectedId(entry.id); setStep(0); }}
          className="block w-full rounded border bg-white p-2 text-left hover:border-teal-600">
          <span className="block font-semibold">{entry.title_vi}</span>
          <span className="block text-[10px] text-slate-600">{entry.topic_vi} · {entry.runtime === 'existing_program' ? 'Có chương trình hiệu ứng' : 'Tài liệu tham khảo, chưa mô phỏng động'}</span>
        </button>)}
        {entries.length > 0 && matches.length === 0 && <p>Không có phản ứng phù hợp.</p>}
      </div>
    </> : <article className="space-y-3">
      <button onClick={() => setSelectedId(null)} className="font-semibold text-teal-800">← Danh mục</button>
      <p className="font-mono break-words rounded bg-white p-2">{selected.equation}</p>
      <p>{selected.conditions.description_vi ?? [selected.conditions.medium, selected.conditions.catalyst,
        selected.conditions.minTemp_c !== undefined ? `Nhiệt độ tối thiểu trong mô hình: ${selected.conditions.minTemp_c} °C` : null].filter(Boolean).join(' · ')}</p>
      <p className="rounded border border-amber-200 bg-amber-50 p-2">{selected.safety_vi} {selected.quantityPolicy}</p>
      <p className="text-slate-600">{selected.protocolStatus === 'qualitative_outline' ? 'Đề cương định tính: cần quy trình cụ thể của giáo viên để thực hành.' : 'Trình tự quan sát riêng cho phản ứng.'}</p>
      <ol className="space-y-2">
        {selected.steps.map((item, index) => <li key={item.order} className={`rounded p-2 ${index === step ? 'bg-white ring-1 ring-teal-600' : 'bg-white/50'}`}>
          <button className="text-left" onClick={() => setStep(index)} aria-current={index === step ? 'step' : undefined}>
            <strong>Bước {item.order}. </strong>{item.instruction_vi}
          </button>
        </li>)}
      </ol>
      <div className="flex justify-between items-center">
        <button disabled={step === 0} onClick={() => setStep(value => value - 1)} className="rounded border bg-white px-2 py-1 disabled:opacity-40">Trước</button>
        <span>Bước đọc {step + 1}/{selected.steps.length}</span>
        <button disabled={step === selected.steps.length - 1} onClick={() => setStep(value => value + 1)} className="rounded border bg-white px-2 py-1 disabled:opacity-40">Tiếp</button>
      </div>
      <p><strong>Quan sát: </strong>{selected.observation_vi}</p>
      <p><strong>Giải thích: </strong>{selected.explanation_vi}</p>
      {selected.effects.after?.precipitate && <p>Kết tủa cuối: {selected.effects.after.precipitate.substance} <span
        aria-label={`Màu kết tủa ${selected.effects.after.precipitate.color}`} className="inline-block h-3 w-3 border border-slate-500"
        style={{ background: selected.effects.after.precipitate.color }} /></p>}
      {!!selected.effects.after?.gasesOffgassed?.length && <p>Khí: {selected.effects.after.gasesOffgassed.map(gas => gas.species).join(', ')}</p>}
      {selected.effects.timeWarp && <p className="text-amber-900">Thời gian được rút gọn: {selected.effects.timeWarp.note_vi ?? `${selected.effects.timeWarp.physical_s} giây vật lý trong mô hình`}. Thời gian hiệu ứng không phải số đo thực nghiệm.</p>}
    </article>}
  </section>;
}

