/**
 * CHEMDEX LAB - RigidBodyLite (K5.1)
 * Lightweight physics body simulating table sliding, bench edges, gravity falls,
 * friction (dry vs wet bench), and floor impacts without heavy physics engines.
 */

export interface MaterialPairProperties {
  friction: number;
  restitution: number;
}

export const TABLE_TOP_Y = -0.135;
export const TABLE_HALF_WIDTH = 16.0;  // X bounds: [-16, 16]
export const TABLE_HALF_DEPTH = 6.75;  // Z bounds: [-6.75, 6.75]
export const FLOOR_Y = -2.5;

export interface RigidBodyState {
  id: string;
  type: string;
  position: [number, number, number];
  velocity: [number, number, number];
  rotationZ: number;
  angularVelocityZ: number;
  mass_kg: number;
  isGrounded: boolean;
  isOnTable: boolean;
  isOnFloor: boolean;
  fallDistance_m: number;
  isWetSurface: boolean;
}

export class RigidBodyLite {
  public state: RigidBodyState;
  private readonly gravity: number = -9.8; // m/s^2

  constructor(
    id: string,
    type: string,
    initialPos: [number, number, number],
    mass_kg: number = 0.15
  ) {
    this.state = {
      id,
      type,
      position: [...initialPos],
      velocity: [0, 0, 0],
      rotationZ: 0,
      angularVelocityZ: 0,
      mass_kg,
      isGrounded: initialPos[1] <= TABLE_TOP_Y,
      isOnTable: true,
      isOnFloor: false,
      fallDistance_m: 0,
      isWetSurface: false
    };
  }

  public applyImpulse(impulse: [number, number, number]): void {
    this.state.velocity[0] += impulse[0] / this.state.mass_kg;
    this.state.velocity[1] += impulse[1] / this.state.mass_kg;
    this.state.velocity[2] += impulse[2] / this.state.mass_kg;
  }

  public setWetSurface(wet: boolean): void {
    this.state.isWetSurface = wet;
  }

  /**
   * Fixed-timestep integrator (e.g. 1/60s or 1/120s).
   * Fully deterministic: zero Math.random() or Date.now().
   */
  public step(dt: number): { hasLandedOnFloor: boolean; impactEnergy_J: number } {
    let hasLandedOnFloor = false;
    let impactEnergy_J = 0;

    const [x, y, z] = this.state.position;
    const isOverTable = Math.abs(x) <= TABLE_HALF_WIDTH && Math.abs(z) <= TABLE_HALF_DEPTH;

    if (isOverTable) {
      this.state.isOnTable = true;
      // Object is over table slab
      if (y > TABLE_TOP_Y) {
        // Free fall towards table
        this.state.velocity[1] += this.gravity * dt;
        this.state.fallDistance_m += Math.abs(this.state.velocity[1] * dt);
        this.state.isGrounded = false;
      } else {
        // Resting / sliding on table
        this.state.position[1] = TABLE_TOP_Y;
        this.state.velocity[1] = 0;
        this.state.isGrounded = true;
        this.state.fallDistance_m = 0;

        // Friction: wet bench has ~0.15 friction, dry bench ~0.65
        const frictionCoeff = this.state.isWetSurface ? 0.15 : 0.65;
        const normalForce = this.state.mass_kg * Math.abs(this.gravity);
        const frictionDecel = (frictionCoeff * normalForce) / this.state.mass_kg;

        const currentSpeedH = Math.hypot(this.state.velocity[0], this.state.velocity[2]);
        if (currentSpeedH > 0.001) {
          const newSpeedH = Math.max(0, currentSpeedH - frictionDecel * dt);
          const ratio = newSpeedH / currentSpeedH;
          this.state.velocity[0] *= ratio;
          this.state.velocity[2] *= ratio;
        } else {
          this.state.velocity[0] = 0;
          this.state.velocity[2] = 0;
        }
      }
    } else {
      // Over table edge -> fall to floor
      this.state.isOnTable = false;
      if (y > FLOOR_Y) {
        this.state.velocity[1] += this.gravity * dt;
        this.state.fallDistance_m += Math.abs(this.state.velocity[1] * dt);
        this.state.isGrounded = false;
      } else {
        // Impact on floor
        this.state.position[1] = FLOOR_Y;
        const vImpact = Math.abs(this.state.velocity[1]);
        impactEnergy_J = 0.5 * this.state.mass_kg * vImpact * vImpact;

        this.state.velocity = [0, 0, 0];
        this.state.isGrounded = true;
        this.state.isOnFloor = true;
        hasLandedOnFloor = true;
      }
    }

    // Update position from velocity
    this.state.position[0] += this.state.velocity[0] * dt;
    this.state.position[1] += this.state.velocity[1] * dt;
    this.state.position[2] += this.state.velocity[2] * dt;

    // Angular damping
    this.state.rotationZ += this.state.angularVelocityZ * dt;
    this.state.angularVelocityZ *= (1 - 5.0 * dt);

    return { hasLandedOnFloor, impactEnergy_J };
  }
}

physicsLite\\Support.ts:
/**
 * CHEMDEX LAB - Physics Lite: Support & Tipping Stability (K5.2 & K5.4)
 * Calculates Center of Mass (COM) including liquid volume, support polygon,
 * and tipping angle thresholds for glassware.
 */

import { getVesselProfile } from '../pour/physics/profiles';

export interface StabilityResult {
  isStable: boolean;
  com: [number, number, number];
  baseRadius: number;
  tippingAngleRad: number; // Maximum tilt angle before tipping over
  tendencyToRoll: boolean; // True for round bottom / spherical vessels
}

/**
 * Calculates vessel stability based on physical geometry, mass distribution,
 * liquid fill level, and support contact polygon.
 */
export function calculateVesselStability(
  type: string,
  liquidVolume_ml: number = 0,
  liquidDensity_g_ml: number = 1.0,
  hasCorkRingOrRack: boolean = false
): StabilityResult {
  const profile = getVesselProfile(type);
  const emptyGlassMass_g = profile.capacity_ml * 0.45; // ~110g for 250ml beaker
  const liquidMass_g = liquidVolume_ml * liquidDensity_g_ml;
  const totalMass_g = emptyGlassMass_g + liquidMass_g;

  // Empty glass COM height above base
  const glassComY = profile.baseY + profile.H * 0.42;

  // Liquid COM height above base
  const fillFraction = Math.max(0, Math.min(1.0, liquidVolume_ml / profile.capacity_ml));
  const liquidHeight = profile.H * fillFraction;
  const liquidComY = profile.baseY + liquidHeight * 0.5;

  // Combined COM Y
  const combinedComY = (emptyGlassMass_g * glassComY + liquidMass_g * liquidComY) / Math.max(1, totalMass_g);
  const comHeightAboveFloor = Math.max(0.1, combinedComY - profile.baseY);

  // Base support radius
  let baseRadius = type === 'cylinder' ? profile.r(profile.baseY) * 0.72 : profile.r(profile.baseY);
  let tendencyToRoll = false;

  if (type === 'test_tube') {
    // Hemispherical bottom cannot stand alone on flat bench
    baseRadius = hasCorkRingOrRack ? 0.35 : 0.02;
    tendencyToRoll = !hasCorkRingOrRack;
  } else if (type === 'flask' && type.includes('round_bottom')) {
    baseRadius = hasCorkRingOrRack ? 0.8 : 0.05;
    tendencyToRoll = !hasCorkRingOrRack;
  }

  // Tipping angle θ_crit = arctan(baseRadius / comHeight)
  const tippingAngleRad = Math.atan2(baseRadius, comHeightAboveFloor);

  return {
    isStable: !tendencyToRoll,
    com: [0, combinedComY, 0],
    baseRadius,
    tippingAngleRad,
    tendencyToRoll
  };
}

/**
 * Checks whether an applied tilt or disturbance exceeds tipping stability.
 */
export function willVesselTip(
  type: string,
  tiltRad: number,
  liquidVolume_ml: number = 0,
  hasCorkRingOrRack: boolean = false
): boolean {
  const stability = calculateVesselStability(type, liquidVolume_ml, 1.0, hasCorkRingOrRack);
  if (stability.tendencyToRoll) return true;
  return Math.abs(tiltRad) > stability.tippingAngleRad;
}

