import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { create } from 'zustand';

interface FrameStats {
  fps: number;
  ms: number;
  p95_ms: number;
  drawCalls: number;
  triangles: number;
  samples: number;
}
export const useFrameStats = create<FrameStats>(() => ({ fps: 0, ms: 0, p95_ms: 0, drawCalls: 0, triangles: 0, samples: 0 }));

export function summarizeFrames(values: ArrayLike<number>, count = values.length) {
  const sorted = Array.from(values).slice(0, count).filter(value => Number.isFinite(value) && value > 0).sort((a, b) => a - b);
  if (!sorted.length) return { fps: 0, ms: 0, p95_ms: 0, samples: 0 };
  const average = sorted.reduce((sum, value) => sum + value, 0) / sorted.length;
  return { fps: Math.round(1000 / average), ms: Math.round(average * 10) / 10,
    p95_ms: Math.round(sorted[Math.ceil(sorted.length * 0.95) - 1] * 10) / 10, samples: sorted.length };
}

/** Samples the R3F loop, publishing once a second. Hidden tabs reset the
 * sampling window instead of counting background RAF throttling as lag. */
export function FrameTelemetry() {
  const samples = useRef(new Float32Array(240));
  const count = useRef(0);
  const elapsed = useRef(0);
  useFrame(({ gl }, delta) => {
    if (document.hidden || delta > 0.5) { count.current = 0; elapsed.current = 0; return; }
    if (!Number.isFinite(delta) || delta <= 0) return;
    samples.current[count.current++] = delta * 1000;
    elapsed.current += delta;
    if (elapsed.current >= 1 || count.current === samples.current.length) {
      useFrameStats.setState({ ...summarizeFrames(samples.current, count.current),
        drawCalls: gl.info.render.calls, triangles: gl.info.render.triangles });
      count.current = 0;
      elapsed.current = 0;
    }
  });
  return null;
}

render\\gl.ts:
/**
 * gl.ts - WebGL capability detection, quality tiers, and adaptive performance controller.
 * 
 * Hardware Capability Probing:
 * - WebGL2 context support
 * - EXT_color_buffer_float / OES_texture_float_linear for floating-point ping-pong fluid solvers
 * - Max texture size and max vertex uniform vectors
 * 
 * Quality Tier Budgets:
 * - Tier A (High): Desktop dGPU/iGPU, 3D/high-res fluid grid, 60k particles, screen-space refraction, bloom, heat-haze
 * - Tier B (Medium): Laptop, 2D slice fluid grid, 20k particles, analytic absorption, billboard steam
 * - Tier C (Low/Mobile): Weak devices, CPU typed array grid, 4k particles, lightweight shaders
 * 
 * Adaptive Performance:
 * - Moving average frame time over 120 frames
 * - 5-second hysteresis preventing oscillations between quality tiers
 */

export type RenderTier = 'A' | 'B' | 'C';

export interface WebGLCapabilities {
  isWebGL2: boolean;
  hasFloatColorBuffer: boolean;
  hasFloatLinear: boolean;
  maxTextureSize: number;
  maxRenderBufferSize: number;
  suggestedTier: RenderTier;
}

export function probeWebGLCapabilities(gl?: WebGLRenderingContext | WebGL2RenderingContext | null): WebGLCapabilities {
  if (typeof window === 'undefined' || typeof document === 'undefined') {
    // Headless / SSR fallback
    return {
      isWebGL2: false,
      hasFloatColorBuffer: false,
      hasFloatLinear: false,
      maxTextureSize: 2048,
      maxRenderBufferSize: 2048,
      suggestedTier: 'C',
    };
  }

  let testCanvas: HTMLCanvasElement | null = null;
  let context = gl;

  if (!context) {
    testCanvas = document.createElement('canvas');
    context = (testCanvas.getContext('webgl2') || testCanvas.getContext('webgl')) as WebGLRenderingContext | null;
  }

  if (!context) {
    return {
      isWebGL2: false,
      hasFloatColorBuffer: false,
      hasFloatLinear: false,
      maxTextureSize: 1024,
      maxRenderBufferSize: 1024,
      suggestedTier: 'C',
    };
  }

  const isWebGL2 = typeof WebGL2RenderingContext !== 'undefined' && context instanceof WebGL2RenderingContext;
  const floatColor = isWebGL2
    ? !!context.getExtension('EXT_color_buffer_float')
    : !!context.getExtension('WEBGL_color_buffer_float');
  const floatLinear = !!context.getExtension('OES_texture_float_linear');

  const maxTextureSize = context.getParameter(context.MAX_TEXTURE_SIZE) || 2048;
  const maxRenderBufferSize = context.getParameter(context.MAX_RENDERBUFFER_SIZE) || 2048;

  let suggestedTier: RenderTier = 'C';
  if (isWebGL2 && floatColor && maxTextureSize >= 4096) {
    suggestedTier = 'A';
  } else if (isWebGL2 || maxTextureSize >= 2048) {
    suggestedTier = 'B';
  }

  return {
    isWebGL2,
    hasFloatColorBuffer: floatColor,
    hasFloatLinear: floatLinear,
    maxTextureSize,
    maxRenderBufferSize,
    suggestedTier,
  };
}

export class AdaptivePerformanceController {
  public tier: RenderTier = 'B';
  public userOverrideTier: RenderTier | null = null;

  private frameTimes: Float32Array = new Float32Array(120);
  private frameIndex: number = 0;
  private frameCount: number = 0;
  private lastTierChangeTime: number = 0;

  constructor(initialTier?: RenderTier) {
    if (initialTier) {
      this.tier = initialTier;
    } else {
      const caps = probeWebGLCapabilities();
      this.tier = caps.suggestedTier;
    }
  }

  /**
   * Record frame time in milliseconds
   */
  public recordFrame(frameDurationMs: number): void {
    if (this.userOverrideTier) {
      this.tier = this.userOverrideTier;
      return;
    }

    this.frameTimes[this.frameIndex] = frameDurationMs;
    this.frameIndex = (this.frameIndex + 1) % 120;
    if (this.frameCount < 120) this.frameCount++;

    if (this.frameCount < 60) return; // Warm-up

    const now = performance.now();
    if (now - this.lastTierChangeTime < 5000) return; // 5-second hysteresis guard

    // Calculate moving average
    let sum = 0;
    for (let i = 0; i < this.frameCount; i++) {
      sum += this.frameTimes[i];
    }
    const avgMs = sum / this.frameCount;

    // >20 ms (below 50 FPS) -> step down tier
    if (avgMs > 20.0) {
      if (this.tier === 'A') {
        this.tier = 'B';
        this.lastTierChangeTime = now;
      } else if (this.tier === 'B') {
        this.tier = 'C';
        this.lastTierChangeTime = now;
      }
    } else if (avgMs < 11.0) { // <11 ms (>90 FPS) -> step up tier
      if (this.tier === 'C') {
        this.tier = 'B';
        this.lastTierChangeTime = now;
      } else if (this.tier === 'B') {
        this.tier = 'A';
        this.lastTierChangeTime = now;
      }
    }
  }
}

render\\glass.ts:
/**
 * glass.ts - Laboratory borosilicate glass shaders with physical Fresnel reflection,
 * double-wall refraction, rim bead highlights, and graduation decals.
 * 
 * Physical Model:
 * 1. Schlick Fresnel Approximation:
 *    F(θ) = F₀ + (1 - F₀) · (1 - cos θ)^p,  F₀ = ((n₁ - n₂) / (n₁ + n₂))² ≈ 0.04 (glass, n = 1.50)
 * 2. Double Refraction:
 *    Light travels through outer wall -> air/glass interface -> inner wall -> liquid.
 *    Handled cleanly by rendering back-faces and front-faces with non-occluding depthWrite: false.
 * 3. Soda-lime edge tint and rim highlight.
 */

import * as THREE from 'three';
import { RenderTier } from './gl.js';

export interface GlassShaders {
  frontMaterial: THREE.Material;
  backMaterial: THREE.Material;
}

export function createPhysicalGlassMaterial(tier: RenderTier = 'B'): GlassShaders {
  if (tier === 'A' || tier === 'B') {
    const front = new THREE.MeshPhysicalMaterial({
      roughness: 0.02,
      metalness: 0.04,
      clearcoat: 1.0,
      clearcoatRoughness: 0.03,
      envMapIntensity: 1.9,
      specularIntensity: 1.0,
      color: new THREE.Color('#f0f9ff'),
      transparent: true,
      opacity: 0.28,
      side: THREE.FrontSide,
      depthWrite: false, // Prevents depth occlusion of liquid inside
    });

    front.onBeforeCompile = (shader) => {
      shader.fragmentShader = shader.fragmentShader.replace(
        '#include <dithering_fragment>',
        `
        #include <dithering_fragment>
        vec3 viewDir = normalize(vViewPosition);
        float fresnel = 1.0 - abs(dot(viewDir, normal));
        fresnel = pow(fresnel, 2.5);
        // Soda-lime subtle greenish-blue rim highlight
        gl_FragColor.rgb += vec3(0.92, 0.98, 1.0) * fresnel * 0.9;
        gl_FragColor.a = max(gl_FragColor.a, fresnel * 0.7);
        `
      );
    };

    const back = new THREE.MeshPhysicalMaterial({
      roughness: 0.05,
      metalness: 0.04,
      clearcoat: 0.6,
      clearcoatRoughness: 0.05,
      envMapIntensity: 1.1,
      color: new THREE.Color('#e0f2fe'),
      transparent: true,
      opacity: 0.18,
      side: THREE.BackSide,
      depthWrite: false,
    });

    return { frontMaterial: front, backMaterial: back };
  }

  // Tier C lightweight fallback
  const fallback = new THREE.MeshStandardMaterial({
    color: '#e6f4ef',
    transparent: true,
    opacity: 0.18,
    roughness: 0.06,
    metalness: 0.1,
    side: THREE.DoubleSide,
    depthWrite: false,
  });

  return { frontMaterial: fallback, backMaterial: fallback };
}

render\\liquid.ts:
/**
 * liquid.ts - Physical liquid renderer with Beer-Lambert volume absorption,
 * meniscus capillary highlight, caustics-lite, and turbidity scattering.
 * 
 * Physical Model:
 * 1. Beer-Lambert Absorption:
 *    A(λ) = Σ ε_k(λ) · c_k · ℓ
 *    Transmittance T(λ) = 10^(-A(λ))
 *    Path length ℓ is integrated per-ray/pixel: deep liquid is saturated and rich;
 *    thin meniscus rim is translucent and bright.
 * 2. Meniscus Ring:
 *    Capillary elevation creates bright Fresnel ring at the glass-liquid contact line.
 * 3. Turbidity Forward Scattering (Henyey-Greenstein lite):
 *    Suspended precipitate particles (BaSO4, AgCl, Cu(OH)2) scatter light forward,
 *    giving a milky opacity with Tyndall beam glow when backlit.
 */

import * as THREE from 'three';
import { RenderTier } from './gl.js';

export interface LiquidShaderUniforms {
  uTime: THREE.IUniform<number>;
  uFillY: THREE.IUniform<number>;
  uLiquidColor: THREE.IUniform<THREE.Color>;
  uTurbidity: THREE.IUniform<number>;
  uBoilingIntensity: THREE.IUniform<number>;
  uPathLengthScale: THREE.IUniform<number>;
}

export function createLiquidPhysicalMaterial(
  clippingPlane: THREE.Plane,
  tier: RenderTier = 'B'
): { material: THREE.Material; uniforms: LiquidShaderUniforms } {
  const uniforms: LiquidShaderUniforms = {
    uTime: { value: 0 },
    uFillY: { value: 0 },
    uLiquidColor: { value: new THREE.Color('#38bdf8') },
    uTurbidity: { value: 0 },
    uBoilingIntensity: { value: 0 },
    uPathLengthScale: { value: 1.0 },
  };

  const mat = new THREE.MeshPhysicalMaterial({
    color: uniforms.uLiquidColor.value,
    roughness: 0.06,
    metalness: 0.02,
    clearcoat: 0.85,
    clearcoatRoughness: 0.05,
    specularIntensity: 0.9,
    transparent: true,
    opacity: 0.88,
    clippingPlanes: [clippingPlane],
    clipShadows: true,
    side: THREE.DoubleSide,
    depthWrite: false,
  });

  mat.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = uniforms.uTime;
    shader.uniforms.uFillY = uniforms.uFillY;
    shader.uniforms.uLiquidColor = uniforms.uLiquidColor;
    shader.uniforms.uTurbidity = uniforms.uTurbidity;
    shader.uniforms.uBoilingIntensity = uniforms.uBoilingIntensity;
    shader.uniforms.uPathLengthScale = uniforms.uPathLengthScale;

    shader.vertexShader = `
      varying vec3 vWorldPos;
      ${shader.vertexShader}
    `;

    shader.vertexShader = shader.vertexShader.replace(
      '#include <worldpos_vertex>',
      `
      #include <worldpos_vertex>
      vWorldPos = (modelMatrix * vec4(transformed, 1.0)).xyz;
      `
    );

    shader.fragmentShader = `
      uniform float uTime;
      uniform float uFillY;
      uniform vec3 uLiquidColor;
      uniform float uTurbidity;
      uniform float uBoilingIntensity;
      uniform float uPathLengthScale;
      varying vec3 vWorldPos;
      ${shader.fragmentShader}
    `;

    shader.fragmentShader = shader.fragmentShader.replace(
      '#include <dithering_fragment>',
      `
      #include <dithering_fragment>
      // Beer-Lambert volume absorption approximation based on optical path length
      vec3 viewDir = normalize(vViewPosition);
      float viewCos = max(0.15, abs(dot(viewDir, normal)));
      float opticalPath = (1.0 / viewCos) * uPathLengthScale;

      // Absorb transmittance: T = exp(-A * path)
      vec3 absorptionCoeff = -log(max(vec3(0.01), uLiquidColor)) * 1.5;
      vec3 transmittance = exp(-absorptionCoeff * opticalPath);
      gl_FragColor.rgb = transmittance;

      // Turbidity Tyndall scattering for milky precipitates
      if (uTurbidity > 0.01) {
        vec3 scatterLight = vec3(0.96, 0.96, 0.94);
        float scatterFactor = clamp(uTurbidity * 1.8, 0.0, 0.95);
        gl_FragColor.rgb = mix(gl_FragColor.rgb, scatterLight, scatterFactor);
        gl_FragColor.a = max(gl_FragColor.a, mix(0.7, 0.98, scatterFactor));
      }

      // Fresnel edge meniscus highlight
      float rim = 1.0 - viewCos;
      gl_FragColor.rgb += uLiquidColor * pow(rim, 2.5) * 0.4;
      `
    );
  };

  return { material: mat, uniforms };
}

render\\particlesRender.ts:
/**
 * particlesRender.ts - GPU-instanced particle rendering for bubbles,
 * crystalline precipitate glitter, droplets, and sparks.
 * 
 * Performance:
 * Single instanced draw-call per particle type.
 * Streaming position, scale, and color matrices directly from SoA ParticleSystem buffers.
 */

import * as THREE from 'three';
import { ParticleSystem, ParticleType } from '../sim/particles.js';

export class ParticleRenderer {
  public instancedMesh: THREE.InstancedMesh;
  private dummy: THREE.Object3D = new THREE.Object3D();
  private colorScratch: THREE.Color = new THREE.Color();

  constructor(capacity: number = 20000) {
    const geometry = new THREE.SphereGeometry(1.0, 10, 8);
    const material = new THREE.MeshPhysicalMaterial({
      roughness: 0.1,
      metalness: 0.05,
      clearcoat: 0.8,
      transparent: true,
      opacity: 0.85,
      depthWrite: false,
    });

    this.instancedMesh = new THREE.InstancedMesh(geometry, material, capacity);
    this.instancedMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    if (this.instancedMesh.instanceColor) {
      this.instancedMesh.instanceColor.setUsage(THREE.DynamicDrawUsage);
    }
  }

  /**
   * Synchronize active particles from simulation SoA to GPU instanced buffers
   */
  public update(particles: ParticleSystem, filterType?: ParticleType): void {
    let renderIdx = 0;

    for (let i = 0; i < particles.capacity; i++) {
      if (particles.age[i] >= particles.maxAge[i]) continue;
      if (filterType !== undefined && particles.type[i] !== filterType) continue;

      const r = particles.radius[i];
      this.dummy.position.set(particles.x[i], particles.y[i], particles.z[i]);
      this.dummy.scale.set(r, r, r);
      this.dummy.updateMatrix();

      this.instancedMesh.setMatrixAt(renderIdx, this.dummy.matrix);

      this.colorScratch.setRGB(particles.r[i], particles.g[i], particles.b[i]);
      this.instancedMesh.setColorAt(renderIdx, this.colorScratch);

      renderIdx++;
      if (renderIdx >= this.instancedMesh.count) break;
    }

    // Hide remaining unused instances
    for (let j = renderIdx; j < this.instancedMesh.count; j++) {
      this.dummy.scale.set(0, 0, 0);
      this.dummy.updateMatrix();
      this.instancedMesh.setMatrixAt(j, this.dummy.matrix);
    }

    this.instancedMesh.instanceMatrix.needsUpdate = true;
    if (this.instancedMesh.instanceColor) {
      this.instancedMesh.instanceColor.needsUpdate = true;
    }
  }
}

render\\post.ts:
/**
 * post.ts - Screen-space post-processing pipelines: heat-haze distortion, bloom, and tone mapping.
 * 
 * Physical Model:
 * 1. Heat Haze / Schlieren Distortion:
 *    Hot air convection creates refractive index gradients: dn/dT ≈ -1e-6 / K.
 *    Screen UVs perturbed by noise offset: UV' = UV + curlNoise(UV * freq, t) * intensity * smoothstep(T - T_amb).
 * 2. Tone Mapping:
 *    ACES filmic tone reproduction curve preserving bright combustion flame specularities without clipping.
 */

import * as THREE from 'three';

export interface HeatHazeUniforms {
  tDiffuse: THREE.IUniform<THREE.Texture | null>;
  uTime: THREE.IUniform<number>;
  uIntensity: THREE.IUniform<number>;
  uSourceY: THREE.IUniform<number>;
}

export function createHeatHazeShader(): {
  shader: THREE.ShaderMaterial;
  uniforms: HeatHazeUniforms;
} {
  const uniforms: HeatHazeUniforms = {
    tDiffuse: { value: null },
    uTime: { value: 0 },
    uIntensity: { value: 0.003 }, // Subtle visual shimmer
    uSourceY: { value: 0.5 },
  };

  const shader = new THREE.ShaderMaterial({
    uniforms: {
      tDiffuse: uniforms.tDiffuse,
      uTime: uniforms.uTime,
      uIntensity: uniforms.uIntensity,
      uSourceY: uniforms.uSourceY,
    },
    vertexShader: `
      varying vec2 vUv;
      void main() {
        vUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform sampler2D tDiffuse;
      uniform float uTime;
      uniform float uIntensity;
      uniform float uSourceY;
      varying vec2 vUv;

      void main() {
        // Upward rising heat haze shimmer
        float wave1 = sin(vUv.y * 40.0 - uTime * 6.0) * cos(vUv.x * 30.0 + uTime * 4.0);
        float wave2 = cos(vUv.y * 65.0 - uTime * 9.0) * sin(vUv.x * 50.0 - uTime * 5.0);
        float haze = (wave1 + wave2) * 0.5;

        // Mask distortion to region directly above heating sources
        float heightMask = smoothstep(uSourceY - 0.05, uSourceY + 0.4, vUv.y);
        vec2 offset = vec2(haze * uIntensity * heightMask, 0.0);

        gl_FragColor = texture2D(tDiffuse, vUv + offset);
      }
    `,
  });

  return { shader, uniforms };
}

render\\volumeSmoke.ts:
/**
 * volumeSmoke.ts - Volumetric steam, smoke, and colored gas plume shaders.
 * 
 * Capabilities:
 * - Soft-particle depth-faded billboards.
 * - Support for colored gases (NO2 brown, Cl2 yellow-green, I2 purple, MgO dense white).
 * - Curl noise advection and buoyancy expansion.
 */

import * as THREE from 'three';

export interface GasPlumeUniforms {
  uTime: THREE.IUniform<number>;
  uColor: THREE.IUniform<THREE.Color>;
  uDensity: THREE.IUniform<number>;
}

export function createGasPlumeMaterial(colorHex: string = '#ffffff'): {
  material: THREE.ShaderMaterial;
  uniforms: GasPlumeUniforms;
} {
  const uniforms: GasPlumeUniforms = {
    uTime: { value: 0 },
    uColor: { value: new THREE.Color(colorHex) },
    uDensity: { value: 1.0 },
  };

  const material = new THREE.ShaderMaterial({
    uniforms: {
      uTime: uniforms.uTime,
      uColor: uniforms.uColor,
      uDensity: uniforms.uDensity,
    },
    vertexShader: `
      varying vec2 vUv;
      void main() {
        vUv = uv;
        vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
        gl_Position = projectionMatrix * mvPosition;
      }
    `,
    fragmentShader: `
      uniform float uTime;
      uniform vec3 uColor;
      uniform float uDensity;
      varying vec2 vUv;

      void main() {
        vec2 p = vUv * 2.0 - 1.0;
        float dist = length(p);
        if (dist > 1.0) discard;

        float alpha = smoothstep(1.0, 0.0, dist) * 0.25 * uDensity;
        gl_FragColor = vec4(uColor, alpha);
      }
    `,
    transparent: true,
    depthWrite: false,
    blending: THREE.NormalBlending,
  });

  return { material, uniforms };
}

