/**
 * bubbles.ts - Physically-based bubble nucleation, rise dynamics, subcooled collapse, and surface bursts.
 * 
 * Physical Models:
 * 1. Fritz Departure Diameter:
 *    D_d = 0.0208 · θ · sqrt(σ / (g (ρ_l - ρ_v)))
 *    θ: contact angle (~45° - 60° on borosilicate glass)
 * 2. Bubble Rise Velocity (Mendelson equation for R > 0.5 mm, Stokes for R < 0.5 mm):
 *    U = sqrt(2 σ / (ρ_l d) + g d / 2)  (clamped 0.15 - 0.35 m/s)
 * 3. Path Wobble:
 *    Lateral oscillation for d > 1.5 mm: A_wobble ≈ 0.3 d, f_wobble ≈ U / (4 d)
 * 4. Subcooled Bubble Collapse ("Singing" Stage, 90°C - 99°C):
 *    Condensation rate: dR/dt ∝ (T_local - T_sat)
 *    If R < R_crit (≈ 0.1 mm) → bubble collapses completely with tick audio impulse.
 * 5. Surface Arrival & Film Burst:
 *    Cap thins → exponential burst → ring ripple impulse, 0-3 Worthington jet droplets,
 *    and Minnaert acoustic frequency: f = 3.26 / R (Hz).
 * 
 * Units: SI internally (m, m/s, s, N/m, kg/m³, Hz)
 */

import { GRAVITY } from '../core/units.js';
import { ParticleSystem, ParticleType } from './particles.js';
import { FreeSurfaceSimulator } from './surface.js';
import { PRNG } from '../core/rng.js';

export interface NucleationSite {
  x: number;          // Position relative to vessel center (m)
  y: number;          // Height from vessel base (m)
  z: number;          // Position relative to vessel center (m)
  baseFreq: number;   // Emission frequency (Hz, 5 - 40 Hz)
  phase: number;      // Phase offset
  timer: number;      // Accumulator (s)
  active: boolean;
}

export interface BubbleSimConfig {
  contactAngleDeg: number;  // θ in degrees (~50° for clean water on glass)
  surfaceTension: number;   // σ (N/m, ~0.0728 N/m)
  liquidDensity: number;    // ρ_l (kg/m³, ~1000 kg/m³)
  vaporDensity: number;     // ρ_v (kg/m³, ~0.598 kg/m³ at 100°C)
  vesselRadius: number;     // Bottom radius of vessel (m)
  numSites: number;         // Number of nucleation sites (default 24)
}

export class BubbleManager {
  public contactAngleDeg: number;
  public surfaceTension: number;
  public liquidDensity: number;
  public vaporDensity: number;
  public vesselRadius: number;

  public sites: NucleationSite[] = [];
  public onBubbleBurst?: (x: number, z: number, radius: number, minnaertFreq: number) => void;
  public onBubbleCollapse?: (x: number, y: number, z: number, freq: number) => void;

  constructor(config: Partial<BubbleSimConfig> = {}, rng?: PRNG) {
    this.contactAngleDeg = config.contactAngleDeg ?? 50.0;
    this.surfaceTension = config.surfaceTension ?? 0.0728;
    this.liquidDensity = config.liquidDensity ?? 1000.0;
    this.vaporDensity = config.vaporDensity ?? 0.598;
    this.vesselRadius = config.vesselRadius ?? 0.04;

    const numSites = config.numSites ?? 24;
    this.initNucleationSites(numSites, rng);
  }

  /**
   * Calculate Fritz bubble departure diameter (m)
   */
  public calculateDepartureDiameter(temperatureK: number): number {
    const deltaRho = Math.max(1.0, this.liquidDensity - this.vaporDensity);
    const laplaceLength = Math.sqrt(this.surfaceTension / (GRAVITY * deltaRho));
    // D_d = 0.0208 * θ * sqrt(σ / (g Δρ))
    const baseDd = 0.0208 * this.contactAngleDeg * laplaceLength;
    return Math.max(0.0008, Math.min(0.006, baseDd)); // Clamp between 0.8 mm and 6 mm
  }

  /**
   * Distribute Poisson-disc-like nucleation sites on bottom plate and lower rim
   */
  private initNucleationSites(count: number, rng?: PRNG): void {
    this.sites = [];
    const R = this.vesselRadius * 0.85;

    for (let i = 0; i < count; i++) {
      // Golden spiral distribution on bottom disc
      const phi = (i + 0.5) * 2.3999632; // Golden ratio angle
      const r = R * Math.sqrt((i + 0.5) / count);
      const x = r * Math.cos(phi);
      const z = r * Math.sin(phi);
      const y = 0.001; // 1 mm above bottom glass

      const freq = 6.0 + (rng ? rng.nextFloat() : Math.random()) * 18.0; // 6 - 24 Hz

      this.sites.push({
        x,
        y,
        z,
        baseFreq: freq,
        phase: (rng ? rng.nextFloat() : Math.random()) * Math.PI * 2,
        timer: 0,
        active: false,
      });
    }
  }

  /**
   * Update bubble nucleation, rise dynamics, subcooling collapse, and surface bursts
   */
  public update(
    dt: number,
    particles: ParticleSystem,
    surface: FreeSurfaceSimulator,
    bulkTempK: number,
    satTempK: number,
    liquidHeight: number,
    heatPowerW: number
  ): void {
    if (dt <= 0) return;

    const departureD = this.calculateDepartureDiameter(bulkTempK);
    const baseDepartureRadius = departureD * 0.5;

    // Activate nucleation sites based on thermal superheating and heat input
    const superheat = bulkTempK - (satTempK - 10.0); // Degassing starts ~10K below sat
    const isBoiling = bulkTempK >= satTempK - 0.5;
    const activeFraction = Math.max(0, Math.min(1.0, superheat / 10.0 + (heatPowerW > 50 ? 0.3 : 0.0)));
    const activeCount = Math.floor(this.sites.length * activeFraction);

    // 1. Nucleation and emission
    for (let s = 0; s < this.sites.length; s++) {
      const site = this.sites[s];
      site.active = s < activeCount;
      if (!site.active) continue;

      site.timer += dt;
      const period = 1.0 / site.baseFreq;

      if (site.timer >= period) {
        site.timer -= period;

        // Fritz departure with ±20% jitter
        const rJitter = baseDepartureRadius * (0.8 + Math.random() * 0.4);
        particles.spawn({
          type: ParticleType.BUBBLE,
          x: site.x + (Math.random() - 0.5) * 0.002,
          y: site.y,
          z: site.z + (Math.random() - 0.5) * 0.002,
          vx: (Math.random() - 0.5) * 0.02,
          vy: 0.18, // Initial detachment velocity
          vz: (Math.random() - 0.5) * 0.02,
          radius: rJitter,
          maxAge: 4.0, // Max travel time
          weight: 1.0,
          r: 0.95,
          g: 0.98,
          b: 1.0,
          a: 0.6,
        });
      }
    }

    // 2. Bubble rise kinematics, subcooled collapse, and surface burst
    for (let i = 0; i < particles.capacity; i++) {
      if (particles.age[i] >= particles.maxAge[i] || particles.type[i] !== ParticleType.BUBBLE) {
        continue;
      }

      const r = particles.radius[i];
      const d = 2.0 * r;

      // Mendelson rise velocity: U = sqrt(2σ / (ρ d) + g d / 2)
      const uRise = Math.max(0.12, Math.min(0.35, Math.sqrt((2.0 * this.surfaceTension) / (this.liquidDensity * d) + (GRAVITY * d) * 0.5)));
      particles.vy[i] = uRise;

      // Path wobble for bubbles larger than 1.5 mm
      if (d > 0.0015) {
        particles.phase[i] += (uRise / (4.0 * d)) * dt * Math.PI * 2;
        const wobbleAmp = 0.25 * d;
        particles.vx[i] = Math.cos(particles.phase[i]) * wobbleAmp * 10.0;
        particles.vz[i] = Math.sin(particles.phase[i]) * wobbleAmp * 10.0;
      }

      // Subcooled bubble condensation collapse (when bulkTemp < satTemp)
      if (bulkTempK < satTempK - 1.0) {
        const subcoolDelta = (satTempK - bulkTempK);
        // Bubble shrinks via condensation: dr/dt = -k * ΔT_sub
        particles.radius[i] -= 0.0003 * subcoolDelta * dt;

        if (particles.radius[i] <= 0.0002) { // Collapsed (200 µm threshold)
          const minnaertCollapse = 3.26 / Math.max(0.0002, particles.radius[i]);
          if (this.onBubbleCollapse) {
            this.onBubbleCollapse(particles.x[i], particles.y[i], particles.z[i], minnaertCollapse);
          }
          particles.kill(i);
          continue;
        }
      } else if (isBoiling) {
        // Growth while rising through saturated liquid
        particles.radius[i] += 0.00015 * dt;
      }

      // 3. Surface arrival check
      if (particles.y[i] >= liquidHeight - 0.002) {
        // Bubble reaches free surface: burst event
        const burstX = particles.x[i];
        const burstZ = particles.z[i];
        const normX = burstX / this.vesselRadius;
        const normZ = burstZ / this.vesselRadius;

        // Surface ripple impulse
        surface.addImpulse(normX, normZ, r * 1.2, 0.06);

        // Minnaert burst frequency: f ≈ 3.26 / R (Hz)
        const minnaertFreq = 3.26 / Math.max(0.0005, r);
        if (this.onBubbleBurst) {
          this.onBubbleBurst(burstX, burstZ, r, minnaertFreq);
        }

        // Worthington jet droplets (0 - 2 droplets)
        if (Math.random() < 0.6) {
          const dropRadius = r * 0.18;
          particles.spawn({
            type: ParticleType.DROPLET,
            x: burstX,
            y: liquidHeight + 0.002,
            z: burstZ,
            vx: (Math.random() - 0.5) * 0.1,
            vy: 0.35 + Math.random() * 0.45, // Ejection upward
            vz: (Math.random() - 0.5) * 0.1,
            radius: dropRadius,
            maxAge: 0.8,
            r: 0.9,
            g: 0.95,
            b: 1.0,
            a: 0.8,
          });
        }

        particles.kill(i);
      }
    }
  }
}

sim\\combustion.ts:
/**
 * combustion.ts - Flame physics, blackbody radiation spectra, flame tests,
 * and burning metal pyrotechnics.
 * 
 * Physical Model:
 * 1. Blackbody Radiation (Planck's Law):
 *    Color temperature mapping from Kelvin:
 *    1000 K (cherry red) -> 1500 K (orange) -> 2000 K (yellow-white) -> 3000 K+ (blinding white, Mg).
 * 2. Flame Structure:
 *    - Premixed Cone (Bunsen air hole open): inner cold cone + outer hot chemiluminescent blue cone.
 *    - Diffusion Flame (Bunsen air hole closed / candle): soot luminescence yellow-orange.
 * 3. Flame Tests (Atomic Emission Spectra):
 *    - Li⁺: crimson (670 nm)
 *    - Na⁺: intense yellow-orange doublet (589 nm) - strong masking of other elements
 *    - K⁺: lilac / pale violet (766 nm)
 *    - Ca²⁺: brick orange-red (622 nm)
 *    - Sr²⁺: intense crimson (650 nm)
 *    - Ba²⁺: pale apple-green (524 nm)
 *    - Cu²⁺: vibrant emerald / azure blue-green (510 nm)
 *    - Borates: vivid green (546 nm)
 * 4. Cobalt-Glass Filter:
 *    Optical absorption band selectively suppresses 589 nm Na emission, unmasking K lilac.
 * 5. Burning Magnesium:
 *    T ≈ 3100 K, blinding white emission, heavy white MgO aerosol.
 * 
 * Units: SI internally (K, nm, W, s)
 */

export interface FlameEmissionColor {
  r: number;
  g: number;
  b: number;
  intensity: number;
}

export const FLAME_TEST_LINES: Record<string, { r: number; g: number; b: number; dominance: number }> = {
  Li: { r: 1.0, g: 0.1, b: 0.2, dominance: 2.0 },      // Crimson
  Na: { r: 1.0, g: 0.72, b: 0.05, dominance: 8.0 },    // Intense yellow-orange (high masking)
  K:  { r: 0.75, g: 0.45, b: 0.95, dominance: 1.0 },   // Lilac / pale violet
  Ca: { r: 1.0, g: 0.35, b: 0.1, dominance: 2.2 },     // Brick orange-red
  Sr: { r: 1.0, g: 0.05, b: 0.15, dominance: 3.5 },    // Crimson red
  Ba: { r: 0.65, g: 0.95, b: 0.25, dominance: 1.8 },   // Apple green
  Cu: { r: 0.1, g: 0.85, b: 0.8, dominance: 3.0 },     // Blue-green
  B:  { r: 0.15, g: 0.95, b: 0.2, dominance: 2.5 },    // Bright green
};

export class CombustionEngine {
  /**
   * Approximate blackbody RGB color from temperature (K)
   */
  public blackbodyColor(tempK: number): { r: number; g: number; b: number } {
    const t = tempK / 100.0;
    let r = 0;
    let g = 0;
    let b = 0;

    // Red
    if (t <= 66) {
      r = 1.0;
    } else {
      r = Math.min(1.0, Math.max(0.0, 1.292936 * Math.pow(t - 60, -0.1332047592)));
    }

    // Green
    if (t <= 66) {
      g = Math.min(1.0, Math.max(0.0, 0.3900815 * Math.log(t) - 0.63184144));
    } else {
      g = Math.min(1.0, Math.max(0.0, 1.12989 * Math.pow(t - 60, -0.0755148492)));
    }

    // Blue
    if (t >= 66) {
      b = 1.0;
    } else if (t <= 19) {
      b = 0.0;
    } else {
      b = Math.min(1.0, Math.max(0.0, 0.543206789 * Math.log(t - 10) - 1.196254));
    }

    return { r, g, b };
  }

  /**
   * Calculate effective flame color with optional atomic species emissions and cobalt glass filter
   */
  public evaluateFlameColor(
    isAirHoleOpen: boolean,
    activeElements: Record<string, number>, // species -> concentration/sample weight
    useCobaltGlass: boolean = false
  ): FlameEmissionColor {
    // 1. Base burner flame
    let r = isAirHoleOpen ? 0.2 : 1.0;
    let g = isAirHoleOpen ? 0.45 : 0.65;
    let b = isAirHoleOpen ? 0.95 : 0.1;
    let totalWeight = 1.0;

    // 2. Add spectral atomic emission lines
    for (const [elem, amount] of Object.entries(activeElements)) {
      if (amount <= 0) continue;
      const test = FLAME_TEST_LINES[elem];
      if (!test) continue;

      let elemWeight = amount * test.dominance;

      // Cobalt glass blocks Na 589nm line by 98%
      if (elem === 'Na' && useCobaltGlass) {
        elemWeight *= 0.02;
      }

      r += test.r * elemWeight;
      g += test.g * elemWeight;
      b += test.b * elemWeight;
      totalWeight += elemWeight;
    }

    // Normalize and scale intensity
    r /= totalWeight;
    g /= totalWeight;
    b /= totalWeight;

    // Cobalt glass filter imparts deep blue-violet tint to the overall scene
    if (useCobaltGlass) {
      r *= 0.35;
      g *= 0.2;
      b *= 1.4;
    }

    return {
      r: Math.min(1.0, r),
      g: Math.min(1.0, g),
      b: Math.min(1.0, b),
      intensity: 1.0 + Math.min(3.0, totalWeight * 0.5),
    };
  }
}

sim\\condensation.ts:
/**
 * condensation.ts - Glass wall condensation, microscopic fog film, discrete droplets,
 * sliding with clear trail deposition, and gravity drips.
 * 
 * Physical Model:
 * 1. Condensation Criterion:
 *    T_glass < T_dew
 * 2. Fog Film Phase:
 *    Microscopic droplet fog coverage θ_c(t) rises with (T_dew - T_glass)
 * 3. Discrete Droplet Growth & Sliding:
 *    dr/dt ∝ (T_dew - T_glass) / r
 *    When droplet radius exceeds pinning threshold r_pin (~1.5 - 2.5 mm, Bond-number criterion),
 *    droplet slides down wall with v ∝ r², sweeping and coalescing smaller droplets along its trail.
 * 4. Drip back:
 *    Droplets reaching liquid level or rim drip into liquid, creating small surface ripple.
 * 
 * Units: SI internally (m, m/s, K, s)
 */

export interface WallDroplet {
  u: number;            // Normalized circumferential angle [0, 1]
  y: number;            // Height along vessel wall (m)
  radius: number;       // Droplet radius (m, 0.2 - 3 mm)
  isSliding: boolean;
  slideVelocity: number;
}

export class CondensationEngine {
  public fogCoverage: number = 0; // [0, 1]
  public droplets: WallDroplet[] = [];
  public maxDroplets: number = 64;
  public pinningRadiusM: number = 0.0022; // 2.2 mm pinning threshold

  public onDrip?: (angleRad: number, radiusM: number) => void;

  /**
   * Evaluate glass wall condensation and droplet dynamics
   */
  public update(
    dt: number,
    glassTempK: number,
    dewPointK: number,
    liquidHeightM: number,
    vesselHeightM: number
  ): void {
    if (dt <= 0) return;

    const deltaT = dewPointK - glassTempK;

    // 1. Fog film coverage
    if (deltaT > 0.5) {
      this.fogCoverage = Math.min(1.0, this.fogCoverage + 0.15 * deltaT * dt);
    } else {
      this.fogCoverage = Math.max(0.0, this.fogCoverage - 0.25 * (glassTempK - dewPointK) * dt);
    }

    // 2. Spawn discrete droplets when fog film is dense
    if (this.fogCoverage > 0.4 && this.droplets.length < this.maxDroplets && Math.random() < 0.15) {
      // Spawn on upper headspace wall
      const spawnY = liquidHeightM + 0.01 + Math.random() * (vesselHeightM - liquidHeightM - 0.015);
      this.droplets.push({
        u: Math.random(),
        y: spawnY,
        radius: 0.0004 + Math.random() * 0.0004, // 0.4 - 0.8 mm initial
        isSliding: false,
        slideVelocity: 0,
      });
    }

    // 3. Droplet growth, coalescence, and sliding
    for (let i = this.droplets.length - 1; i >= 0; i--) {
      const drop = this.droplets[i];

      if (deltaT > 0) {
        // Growth rate: dr/dt = k * ΔT / r
        drop.radius += (0.00002 * deltaT / Math.max(0.0005, drop.radius)) * dt;
      } else {
        // Evaporative shrinkage
        drop.radius -= 0.00005 * (glassTempK - dewPointK) * dt;
        if (drop.radius <= 0.0002) {
          this.droplets.splice(i, 1);
          continue;
        }
      }

      // Check pinning threshold
      if (drop.radius >= this.pinningRadiusM) {
        drop.isSliding = true;
        // Sliding velocity: v ∝ r²
        drop.slideVelocity = 15.0 * drop.radius * drop.radius; // ~0.05 - 0.15 m/s
      }

      if (drop.isSliding) {
        drop.y -= drop.slideVelocity * dt;

        // Drip back into liquid surface
        if (drop.y <= liquidHeightM) {
          if (this.onDrip) {
            this.onDrip(drop.u * Math.PI * 2, drop.radius);
          }
          this.droplets.splice(i, 1);
        }
      }
    }
  }
}

sim\\contents.ts:
/**
 * MULTI-PHASE VESSEL CONTENTS MODEL AND CONSERVATION TRACKER (§5.1)
 * Rule 3 & 10: All internal quantities strictly in SI units.
 * - Liquid phase: volume (m^3), solvent mass (kg), species moles (mol), T (K), density, viscosity
 * - Solids: array of solid items with mass, surface area, particle count
 * - Gas headspace: composition, temperature, produced moles
 * - Sediment bed: height, mass, porosity, compaction
 * - Suspended precipitate population: N (m^-3), mean radius r (m)
 * - Conservation invariant telemetry: relative mass error target < 1e-3
 */

import { CONSTANTS, kelvinToCelsius, m3ToMl, kgToGrams, gramsToKg } from '../core/units';
import { SUBSTANCE_DATABASE, PhysicalSubstance } from '../chem/substances';
import { calculateWaterDensity, calculateWaterViscosity } from '../chem/thermo';

export interface SolidContentItem {
  id: string;
  substanceId: string;
  mass_kg: number;
  surfaceArea_m2: number;
  particleCount: number;
  morphology: 'crystal' | 'powder' | 'granular' | 'ribbon' | 'chunk' | 'floc';
  isSubmerged: boolean;
}

export interface SuspendedPrecipitatePopulation {
  substanceId: string;
  numberDensity_m3: number;  // N nuclei/m^3
  meanRadius_m: number;      // r_bar
  totalMass_kg: number;
  turbidityScatter: number;  // Optical scattering factor
}

export interface SedimentBedModel {
  substanceId: string;
  mass_kg: number;
  thickness_m: number;       // Layer height on bottom
  porosity: number;          // 0.4 (dense crystals) to 0.95 (fluffy flocs)
  color: string;
}

export interface GasHeadspaceModel {
  moles: Record<string, number>;
  totalMolesProduced: number;
  temperature_K: number;
  displacedVolume_m3: number; // Volume displaced by evolved gas (nRT/P)
}

export interface ConservationTelemetry {
  initialTotalMass_kg: number;
  currentTotalMass_kg: number;
  massError_rel: number;      // |m_curr - m_init| / m_init
  netIonicCharge: number;     // sum(z_i * n_i)
  accumulatedEnergy_J: number;
}

export class MultiPhaseContents {
  public vesselId: string;

  // Liquid Phase
  public volume_m3: number = 0;
  public solventMass_kg: number = 0; // Liquid water solvent mass
  public dissolvedMoles: Record<string, number> = {}; // mol of each dissolved species
  public temperature_K: number = CONSTANTS.T_ROOM;
  public glassTemp_K: number = CONSTANTS.T_ROOM;
  public ph: number = 7.0;

  // Multi-Phase Entities
  public solids: SolidContentItem[] = [];
  public sediment: SedimentBedModel | null = null;
  public suspended: SuspendedPrecipitatePopulation | null = null;
  public gasHeadspace: GasHeadspaceModel = {
    moles: {},
    totalMolesProduced: 0,
    temperature_K: CONSTANTS.T_ROOM,
    displacedVolume_m3: 0
  };

  // Conservation Bookkeeping
  public initialMass_kg: number = 0;
  public cumulativeMassAdded_kg: number = 0;
  public cumulativeMassLost_kg: number = 0; // Via evaporation/boiling/gas release

  constructor(vesselId: string) {
    this.vesselId = vesselId;
  }

  /**
   * Resets contents to clean empty vessel
   */
  public clear(): void {
    this.volume_m3 = 0;
    this.solventMass_kg = 0;
    this.dissolvedMoles = {};
    this.temperature_K = CONSTANTS.T_ROOM;
    this.glassTemp_K = CONSTANTS.T_ROOM;
    this.ph = 7.0;
    this.solids = [];
    this.sediment = null;
    this.suspended = null;
    this.gasHeadspace = {
      moles: {},
      totalMolesProduced: 0,
      temperature_K: CONSTANTS.T_ROOM,
      displacedVolume_m3: 0
    };
    this.initialMass_kg = 0;
    this.cumulativeMassAdded_kg = 0;
    this.cumulativeMassLost_kg = 0;
  }

  /**
   * Computes bulk liquid density (kg/m^3) including dissolved solute mass and thermal expansion
   */
  public getDensity_kg_m3(): number {
    const rho_water = calculateWaterDensity(this.temperature_K);
    if (this.volume_m3 <= 1e-8) return rho_water;

    let totalSoluteMass_kg = 0;
    for (const [subId, moles] of Object.entries(this.dissolvedMoles)) {
      const sub = SUBSTANCE_DATABASE[subId];
      if (sub && moles > 0) {
        totalSoluteMass_kg += moles * sub.molarMass;
      }
    }

    const totalLiquidMass = this.solventMass_kg + totalSoluteMass_kg;
    return Math.max(900.0, totalLiquidMass / this.volume_m3);
  }

  /**
   * Computes dynamic fluid viscosity in Pa·s
   */
  public getViscosity_Pa_s(): number {
    const baseViscosity = calculateWaterViscosity(this.temperature_K);
    // Solute concentration viscosity boost (Jones-Dole equation approximation: eta = eta0 * (1 + A*sqrt(c) + B*c))
    let totalConcentration_M = 0;
    const vol_L = Math.max(1e-4, this.volume_m3 * 1000.0);
    for (const moles of Object.values(this.dissolvedMoles)) {
      totalConcentration_M += moles / vol_L;
    }
    const B_visc = 0.085;
    return baseViscosity * (1.0 + B_visc * totalConcentration_M);
  }

  /**
   * Computes authoritative total mass of the contents (solvent + solutes + solids + sediment) in kg
   */
  public getTotalMass_kg(): number {
    let mass = this.solventMass_kg;

    // Dissolved solutes
    for (const [subId, moles] of Object.entries(this.dissolvedMoles)) {
      const sub = SUBSTANCE_DATABASE[subId];
      if (sub && moles > 0) {
        mass += moles * sub.molarMass;
      }
    }

    // Solids
    for (const s of this.solids) {
      mass += s.mass_kg;
    }

    // Sediment bed
    if (this.sediment) {
      mass += this.sediment.mass_kg;
    }

    // Suspended particles
    if (this.suspended) {
      mass += this.suspended.totalMass_kg;
    }

    return mass;
  }

  /**
   * Adds solvent (water) in kg and updates volume based on density
   */
  public addSolventWater(mass_kg: number, temp_K = CONSTANTS.T_ROOM): void {
    if (mass_kg <= 0) return;
    const rho = calculateWaterDensity(temp_K);
    const addedVol_m3 = mass_kg / rho;

    // Thermal mixing: (m1*T1 + m2*T2) / (m1 + m2)
    const totalMass = this.solventMass_kg + mass_kg;
    this.temperature_K = (this.solventMass_kg * this.temperature_K + mass_kg * temp_K) / totalMass;
    this.solventMass_kg += mass_kg;
    this.volume_m3 += addedVol_m3;
    this.cumulativeMassAdded_kg += mass_kg;
  }

  /**
   * Adds a dissolved species directly to the liquid phase
   */
  public addDissolvedSpecies(substanceId: string, moles: number): void {
    if (moles <= 0) return;
    const sub = SUBSTANCE_DATABASE[substanceId];
    this.dissolvedMoles[substanceId] = (this.dissolvedMoles[substanceId] || 0) + moles;
    if (sub) {
      this.cumulativeMassAdded_kg += moles * sub.molarMass;
    }
  }

  /**
   * Adds a solid object (powder, crystals, metal piece) to the vessel
   */
  public addSolid(substanceId: string, mass_kg: number, morphology: SolidContentItem['morphology'] = 'powder'): void {
    if (mass_kg <= 0) return;
    const sub = SUBSTANCE_DATABASE[substanceId];
    const density = sub ? sub.density : 3000.0;
    const vol_m3 = mass_kg / density;

    // Approximate specific surface area (m^2)
    const particleRadius_m = morphology === 'powder' ? 20e-6 : (morphology === 'ribbon' ? 2e-3 : 500e-6);
    const area_m2 = (3.0 * vol_m3) / particleRadius_m;

    this.solids.push({
      id: `solid_${Date.now()}_${Math.random().toString(36).substr(2, 4)}`,
      substanceId,
      mass_kg,
      surfaceArea_m2: area_m2,
      particleCount: Math.max(1, Math.round(vol_m3 / ((4 / 3) * Math.PI * Math.pow(particleRadius_m, 3)))),
      morphology,
      isSubmerged: this.volume_m3 > 1e-6
    });

    this.cumulativeMassAdded_kg += mass_kg;
  }

  /**
   * Returns molar concentration vector in mol/L (M)
   */
  public getConcentrations_M(): Record<string, number> {
    const vol_L = Math.max(1e-5, this.volume_m3 * 1000.0);
    const concs: Record<string, number> = {};
    for (const [subId, moles] of Object.entries(this.dissolvedMoles)) {
      concs[subId] = moles / vol_L;
    }
    return concs;
  }

  /**
   * Computes conservation error metrics (§0 Rule 3)
   */
  public getConservationTelemetry(): ConservationTelemetry {
    const currentMass = this.getTotalMass_kg();
    const expectedMass = this.initialMass_kg + this.cumulativeMassAdded_kg - this.cumulativeMassLost_kg;
    const massDiff = Math.abs(currentMass - expectedMass);
    const massError_rel = expectedMass > 1e-6 ? massDiff / expectedMass : 0;

    // Net ionic charge check: sum(z_i * n_i)
    let netCharge = 0;
    for (const [subId, moles] of Object.entries(this.dissolvedMoles)) {
      const sub = SUBSTANCE_DATABASE[subId];
      if (sub && sub.ions) {
        for (const ion of sub.ions) {
          netCharge += moles * ion.n * ion.charge;
        }
      }
    }

    return {
      initialTotalMass_kg: this.initialMass_kg,
      currentTotalMass_kg: currentMass,
      massError_rel,
      netIonicCharge: netCharge,
      accumulatedEnergy_J: 0
    };
  }
}

