/**
 * fluidGrid.ts - 2D Stable-Fluids solver (Stam 1999) with MacCormack advection,
 * vorticity confinement, buoyancy, and multi-species transport.
 * 
 * Physical Model:
 * 1. Incompressible Navier-Stokes equations:
 *    ∂u/∂t = -(u · ∇)u + ν ∇²u - (1/ρ) ∇p + f_buoyancy + f_ext + f_vorticity
 *    ∇ · u = 0
 * 2. Buoyancy (Boussinesq approximation):
 *    f_buoyancy = g · [β_T (T - T_ref) - Σ γ_k (c_k - c_ref)] ŷ
 * 3. MacCormack Advection with Min/Max Clamping:
 *    Forward advection φ_f = SL(φ_n, u)
 *    Backward advection φ_b = SL(φ_f, -u)
 *    Error-corrected φ^* = φ_f + 0.5 * (φ_n - φ_b)
 *    Clamped to min/max of 4 neighbor cells in φ_n to prevent spurious oscillations.
 * 4. Vorticity Confinement (Steinhoff & Underhill):
 *    ω = ∂v/∂x - ∂u/∂y
 *    N = ∇|ω| / (|∇|ω|| + ε)
 *    f_vorticity = ε_vc · Δx · (N_x, N_y) × ω
 * 5. Pressure Projection:
 *    Poisson equation ∇²p = (ρ / Δt) ∇ · u
 *    Solved via Red-Black Gauss-Seidel or Jacobi relaxation with warm start.
 * 6. Multi-species advection:
 *    Each dissolved species and temperature field advected synchronously with the fluid.
 * 
 * Units: SI internally (m, s, m/s, K, mol/m³, Pa)
 */

import { GRAVITY } from '../core/units.js';

export interface FluidGridConfig {
  nx: number;                 // Grid width (horizontal cells, e.g. 64)
  ny: number;                 // Grid height (vertical cells, e.g. 96)
  domainWidth: number;        // Physical width (m, e.g. 0.08 m = 80 mm)
  domainHeight: number;       // Physical height (m, e.g. 0.12 m = 120 mm)
  viscosity: number;          // Kinematic viscosity ν (m²/s, water ≈ 1e-6, eddy-boosted ≈ 1e-4)
  vorticityStrength: number;  // Vorticity confinement ε_vc (0.2 - 0.5)
  pressureIters: number;      // Gauss-Seidel/Jacobi iterations (20 - 40)
  maxSpecies: number;         // Max tracked species fields (default 8)
}

export class FluidGrid2D {
  public readonly nx: number;
  public readonly ny: number;
  public readonly numCells: number;
  public readonly dx: number;
  public readonly dy: number;
  public readonly invDx: number;
  public readonly invDy: number;

  public viscosity: number;
  public vorticityStrength: number;
  public pressureIters: number;
  public maxSpecies: number;

  // Velocity fields: u (horizontal), v (vertical)
  public u: Float32Array;
  public v: Float32Array;
  public u0: Float32Array;
  public v0: Float32Array;

  // Pressure and divergence
  public p: Float32Array;
  public div: Float32Array;

  // Vorticity fields
  public curl: Float32Array;

  // Temperature field (Kelvin)
  public temp: Float32Array;
  public temp0: Float32Array;
  public tRef: number = 293.15; // 20 °C

  // Cell solid/fluid mask: 1.0 = fluid, 0.0 = solid glass wall / outside
  public mask: Float32Array;

  // Species concentration fields (mol/m³)
  // Stored as flattened array: maxSpecies * numCells
  public species: Float32Array;
  public species0: Float32Array;
  public speciesNames: string[] = [];

  constructor(config: Partial<FluidGridConfig> = {}) {
    this.nx = config.nx ?? 64;
    this.ny = config.ny ?? 96;
    this.numCells = this.nx * this.ny;

    const width = config.domainWidth ?? 0.08;
    const height = config.domainHeight ?? 0.12;

    this.dx = width / this.nx;
    this.dy = height / this.ny;
    this.invDx = 1.0 / this.dx;
    this.invDy = 1.0 / this.dy;

    this.viscosity = config.viscosity ?? 1e-4; // Eddy-boosted for stable grid scale
    this.vorticityStrength = config.vorticityStrength ?? 0.35;
    this.pressureIters = config.pressureIters ?? 25;
    this.maxSpecies = config.maxSpecies ?? 8;

    this.u = new Float32Array(this.numCells);
    this.v = new Float32Array(this.numCells);
    this.u0 = new Float32Array(this.numCells);
    this.v0 = new Float32Array(this.numCells);

    this.p = new Float32Array(this.numCells);
    this.div = new Float32Array(this.numCells);
    this.curl = new Float32Array(this.numCells);

    this.temp = new Float32Array(this.numCells);
    this.temp0 = new Float32Array(this.numCells);
    this.temp.fill(293.15); // Default room temp

    this.mask = new Float32Array(this.numCells);
    this.mask.fill(1.0); // Default all fluid inside domain

    this.species = new Float32Array(this.numCells * this.maxSpecies);
    this.species0 = new Float32Array(this.numCells * this.maxSpecies);
  }

  /**
   * Set vessel boundary mask: cells outside radius(y) or above surface are marked solid/inactive
   */
  public setBoundaryMask(radiusAtY: (y: number) => number, liquidHeight: number): void {
    const halfWidth = (this.nx * this.dx) * 0.5;

    for (let j = 0; j < this.ny; j++) {
      const y = (j + 0.5) * this.dy;
      const rLimit = radiusAtY(y);
      const isAboveSurface = y > liquidHeight;

      for (let i = 0; i < this.nx; i++) {
        const x = (i + 0.5) * this.dx - halfWidth;
        const idx = j * this.nx + i;

        if (isAboveSurface || Math.abs(x) > rLimit) {
          this.mask[idx] = 0.0; // Inactive or wall
          this.u[idx] = 0.0;
          this.v[idx] = 0.0;
        } else {
          this.mask[idx] = 1.0; // Active fluid
        }
      }
    }
  }

  /**
   * Register a chemical species index
   */
  public getOrCreateSpeciesSlot(speciesId: string): number {
    const existing = this.speciesNames.indexOf(speciesId);
    if (existing >= 0) return existing;
    if (this.speciesNames.length < this.maxSpecies) {
      this.speciesNames.push(speciesId);
      return this.speciesNames.length - 1;
    }
    return -1; // Exceeded maxSpecies
  }

  /**
   * Inject localized fluid velocity and reagent plume (e.g. from dropper or pour stream)
   */
  public injectSource(
    normX: number,
    normY: number,
    radiusNorm: number,
    uInj: number,
    vInj: number,
    tempK: number,
    speciesAmounts: Array<{ slot: number; conc: number }>
  ): void {
    const ci = Math.floor(normX * this.nx);
    const cj = Math.floor(normY * this.ny);
    const rCells = Math.max(1, Math.floor(radiusNorm * this.nx));

    const minI = Math.max(1, ci - rCells);
    const maxI = Math.min(this.nx - 2, ci + rCells);
    const minJ = Math.max(1, cj - rCells);
    const maxJ = Math.min(this.ny - 2, cj + rCells);

    for (let j = minJ; j <= maxJ; j++) {
      for (let i = minI; i <= maxI; i++) {
        const idx = j * this.nx + i;
        if (this.mask[idx] <= 0) continue;

        const di = i - ci;
        const dj = j - cj;
        const dist2 = di * di + dj * dj;
        if (dist2 <= rCells * rCells) {
          const factor = 1.0 - Math.sqrt(dist2) / (rCells + 0.1);
          this.u[idx] += uInj * factor;
          this.v[idx] += vInj * factor;
          this.temp[idx] += (tempK - this.temp[idx]) * factor * 0.5;

          for (const sp of speciesAmounts) {
            if (sp.slot >= 0 && sp.slot < this.maxSpecies) {
              const spOffset = sp.slot * this.numCells;
              this.species[spOffset + idx] += sp.conc * factor;
            }
          }
        }
      }
    }
  }

  /**
   * Advance fluid simulation by dt seconds
   */
  public step(dt: number): void {
    if (dt <= 0) return;

    // 1. Add buoyancy and body forces
    this.applyForces(dt);

    // 2. Vorticity confinement
    this.applyVorticityConfinement(dt);

    // 3. Advect velocity with MacCormack
    this.advectVelocityMacCormack(dt);

    // 4. Project velocity to divergence-free
    this.project();

    // 5. Advect temperature
    this.advectScalarMacCormack(this.temp, this.temp0, dt, 273.15, 373.15);

    // 6. Advect all chemical species
    for (let s = 0; s < this.speciesNames.length; s++) {
      const offset = s * this.numCells;
      const spSub = this.species.subarray(offset, offset + this.numCells);
      const spSub0 = this.species0.subarray(offset, offset + this.numCells);
      this.advectScalarMacCormack(spSub, spSub0, dt, 0.0, 1e4);
    }
  }

  /**
   * Apply thermal buoyancy and bottom friction
   */
  private applyForces(dt: number): void {
    const betaT = 2.1e-4; // Thermal expansion coeff for water (1/K)
    const tRef = this.tRef;

    for (let j = 0; j < this.ny; j++) {
      const isBottomLayer = j <= 1;
      const row = j * this.nx;

      for (let i = 0; i < this.nx; i++) {
        const idx = row + i;
        if (this.mask[idx] <= 0) continue;

        // Thermal buoyancy: f_y = g * β * (T - T_ref)
        const dT = this.temp[idx] - tRef;
        const fBuoyancy = GRAVITY * betaT * dT;
        this.v[idx] += fBuoyancy * dt;

        // Bottom friction to drive realistic secondary boundary layer drag (Ekman-like)
        if (isBottomLayer) {
          this.u[idx] *= Math.max(0, 1.0 - 5.0 * dt);
        }

        // Clamp max physical velocities to prevent numerical instability (|u| <= 1.2 m/s)
        const speed2 = this.u[idx] * this.u[idx] + this.v[idx] * this.v[idx];
        if (speed2 > 1.44) {
          const invSpeed = 1.2 / Math.sqrt(speed2);
          this.u[idx] *= invSpeed;
          this.v[idx] *= invSpeed;
        }
      }
    }
  }

  /**
   * Vorticity confinement restores small turbulent eddies dissipated by grid
   */
  private applyVorticityConfinement(dt: number): void {
    if (this.vorticityStrength <= 0) return;

    const nx = this.nx;
    const ny = this.ny;
    const invTwoDx = 0.5 * this.invDx;
    const invTwoDy = 0.5 * this.invDy;

    // 1. Compute curl: ω = ∂v/∂x - ∂u/∂y
    for (let j = 1; j < ny - 1; j++) {
      const row = j * nx;
      for (let i = 1; i < nx - 1; i++) {
        const idx = row + i;
        if (this.mask[idx] <= 0) {
          this.curl[idx] = 0;
          continue;
        }
        const dvDx = (this.v[idx + 1] - this.v[idx - 1]) * invTwoDx;
        const duDy = (this.u[idx + nx] - this.u[idx - nx]) * invTwoDy;
        this.curl[idx] = dvDx - duDy;
      }
    }

    // 2. Confinement force: f = ε * dx * (N × ω)
    const coeff = this.vorticityStrength * this.dx;
    for (let j = 2; j < ny - 2; j++) {
      const row = j * nx;
      for (let i = 2; i < nx - 2; i++) {
        const idx = row + i;
        if (this.mask[idx] <= 0) continue;

        // Gradient of absolute curl magnitude |ω|
        const dCurlDx = (Math.abs(this.curl[idx + 1]) - Math.abs(this.curl[idx - 1])) * invTwoDx;
        const dCurlDy = (Math.abs(this.curl[idx + nx]) - Math.abs(this.curl[idx - nx])) * invTwoDy;

        const len = Math.sqrt(dCurlDx * dCurlDx + dCurlDy * dCurlDy) + 1e-5;
        const nxGrad = dCurlDx / len;
        const nyGrad = dCurlDy / len;

        const omega = this.curl[idx];
        // 2D cross product: N × ω = (ny * ω, -nx * ω)
        this.u[idx] += coeff * (nyGrad * omega) * dt;
        this.v[idx] += coeff * (-nxGrad * omega) * dt;
      }
    }
  }

  /**
   * Semi-Lagrangian advection step for a scalar field
   */
  private sampleBilinear(field: Float32Array, x: number, y: number): number {
    const fx = Math.max(0.5, Math.min(this.nx - 1.5, x * this.invDx - 0.5));
    const fy = Math.max(0.5, Math.min(this.ny - 1.5, y * this.invDy - 0.5));

    const i0 = Math.floor(fx);
    const j0 = Math.floor(fy);
    const i1 = i0 + 1;
    const j1 = j0 + 1;

    const s1 = fx - i0;
    const s0 = 1.0 - s1;
    const t1 = fy - j0;
    const t0 = 1.0 - t1;

    const row0 = j0 * this.nx;
    const row1 = j1 * this.nx;

    return (
      s0 * (t0 * field[row0 + i0] + t1 * field[row1 + i0]) +
      s1 * (t0 * field[row0 + i1] + t1 * field[row1 + i1])
    );
  }

  /**
   * MacCormack advection for velocity field with Min/Max clamping
   */
  private advectVelocityMacCormack(dt: number): void {
    const nx = this.nx;
    const ny = this.ny;

    // Copy current state to u0, v0
    this.u0.set(this.u);
    this.v0.set(this.v);

    // Forward step: u_f = SL(u0, u0, dt)
    for (let j = 1; j < ny - 1; j++) {
      const y = (j + 0.5) * this.dy;
      const row = j * nx;
      for (let i = 1; i < nx - 1; i++) {
        const idx = row + i;
        if (this.mask[idx] <= 0) continue;

        const x = (i + 0.5) * this.dx;
        const traceX = x - this.u0[idx] * dt;
        const traceY = y - this.v0[idx] * dt;

        this.u[idx] = this.sampleBilinear(this.u0, traceX, traceY);
        this.v[idx] = this.sampleBilinear(this.v0, traceX, traceY);
      }
    }

    // Clamp MacCormack correction to local min/max of 4 neighbor cells to prevent ringing
    for (let j = 1; j < ny - 1; j++) {
      const row = j * nx;
      for (let i = 1; i < nx - 1; i++) {
        const idx = row + i;
        if (this.mask[idx] <= 0) continue;

        const uMin = Math.min(this.u0[idx], this.u0[idx - 1], this.u0[idx + 1], this.u0[idx - nx], this.u0[idx + nx]);
        const uMax = Math.max(this.u0[idx], this.u0[idx - 1], this.u0[idx + 1], this.u0[idx - nx], this.u0[idx + nx]);
        const vMin = Math.min(this.v0[idx], this.v0[idx - 1], this.v0[idx + 1], this.v0[idx - nx], this.v0[idx + nx]);
        const vMax = Math.max(this.v0[idx], this.v0[idx - 1], this.v0[idx + 1], this.v0[idx - nx], this.v0[idx + nx]);

        this.u[idx] = Math.max(uMin, Math.min(uMax, this.u[idx]));
        this.v[idx] = Math.max(vMin, Math.min(vMax, this.v[idx]));
      }
    }
  }

  /**
   * MacCormack advection for scalar fields (temperature, species concentration)
   */
  private advectScalarMacCormack(
    field: Float32Array,
    field0: Float32Array,
    dt: number,
    minBound: number,
    maxBound: number
  ): void {
    const nx = this.nx;
    const ny = this.ny;

    field0.set(field);

    for (let j = 1; j < ny - 1; j++) {
      const y = (j + 0.5) * this.dy;
      const row = j * nx;
      for (let i = 1; i < nx - 1; i++) {
        const idx = row + i;
        if (this.mask[idx] <= 0) continue;

        const x = (i + 0.5) * this.dx;
        const traceX = x - this.u[idx] * dt;
        const traceY = y - this.v[idx] * dt;

        const val = this.sampleBilinear(field0, traceX, traceY);

        // Clamp to local 4-neighborhood min/max
        const nMin = Math.min(field0[idx], field0[idx - 1], field0[idx + 1], field0[idx - nx], field0[idx + nx]);
        const nMax = Math.max(field0[idx], field0[idx - 1], field0[idx + 1], field0[idx - nx], field0[idx + nx]);

        field[idx] = Math.max(Math.max(minBound, nMin), Math.min(Math.min(maxBound, nMax), val));
      }
    }
  }

  /**
   * Pressure projection step (Helmholtz-Hodge decomposition):
   * ∇²p = ∇ · u*
   * u = u* - ∇p
   */
  public project(): void {
    const nx = this.nx;
    const ny = this.ny;
    const invTwoDx = 0.5 * this.invDx;
    const invTwoDy = 0.5 * this.invDy;

    // 1. Compute velocity divergence: div = (∂u/∂x + ∂v/∂y)
    for (let j = 1; j < ny - 1; j++) {
      const row = j * nx;
      for (let i = 1; i < nx - 1; i++) {
        const idx = row + i;
        if (this.mask[idx] <= 0) {
          this.div[idx] = 0;
          continue;
        }

        const duDx = (this.u[idx + 1] - this.u[idx - 1]) * invTwoDx;
        const dvDy = (this.v[idx + nx] - this.v[idx - nx]) * invTwoDy;
        this.div[idx] = -(duDx + dvDy);
      }
    }

    // 2. Solve Poisson equation for pressure using Red-Black Gauss-Seidel
    const h2 = this.dx * this.dy;
    const invH2Sum = 1.0 / (2.0 * (this.dx * this.dx + this.dy * this.dy));

    for (let iter = 0; iter < this.pressureIters; iter++) {
      // Red-black coloring for fast convergence and parallelism
      for (let pass = 0; pass < 2; pass++) {
        for (let j = 1; j < ny - 1; j++) {
          const row = j * nx;
          const startCol = 1 + ((j + pass) % 2);

          for (let i = startCol; i < nx - 1; i += 2) {
            const idx = row + i;
            if (this.mask[idx] <= 0) continue;

            const pL = this.mask[idx - 1] > 0 ? this.p[idx - 1] : this.p[idx];
            const pR = this.mask[idx + 1] > 0 ? this.p[idx + 1] : this.p[idx];
            const pB = this.mask[idx - nx] > 0 ? this.p[idx - nx] : this.p[idx];
            const pT = this.mask[idx + nx] > 0 ? this.p[idx + nx] : this.p[idx];

            this.p[idx] = ((pL + pR) * this.dy * this.dy + (pB + pT) * this.dx * this.dx + this.div[idx] * h2 * h2) * invH2Sum;
          }
        }
      }
    }

    // 3. Subtract pressure gradient: u -= ∂p/∂x, v -= ∂p/∂y
    for (let j = 1; j < ny - 1; j++) {
      const row = j * nx;
      for (let i = 1; i < nx - 1; i++) {
        const idx = row + i;
        if (this.mask[idx] <= 0) {
          this.u[idx] = 0;
          this.v[idx] = 0;
          continue;
        }

        const dpDx = (this.p[idx + 1] - this.p[idx - 1]) * invTwoDx;
        const dpDy = (this.p[idx + nx] - this.p[idx - nx]) * invTwoDy;

        this.u[idx] -= dpDx;
        this.v[idx] -= dpDy;
      }
    }
  }

  /**
   * Compute max L2 divergence norm across all active fluid cells
   * Incompressible flow requires ||∇ · u|| -> 0 (target < 1e-3)
   */
  public computeDivergenceNorm(): number {
    const nx = this.nx;
    const ny = this.ny;
    const invTwoDx = 0.5 * this.invDx;
    const invTwoDy = 0.5 * this.invDy;

    let sumSq = 0;
    let count = 0;

    for (let j = 1; j < ny - 1; j++) {
      const row = j * nx;
      for (let i = 1; i < nx - 1; i++) {
        const idx = row + i;
        if (this.mask[idx] <= 0) continue;

        const duDx = (this.u[idx + 1] - this.u[idx - 1]) * invTwoDx;
        const dvDy = (this.v[idx + nx] - this.v[idx - nx]) * invTwoDy;
        const d = duDx + dvDy;
        sumSq += d * d;
        count++;
      }
    }

    return count > 0 ? Math.sqrt(sumSq / count) : 0;
  }
}

sim\\heater.ts:
/**
 * heater.ts - Physical thermal models for laboratory heating and cooling equipment.
 * 
 * Physical Models:
 * 1. Hot Plate:
 *    dT_plate/dt = (T_set - T_plate) / τ_plate  (first-order thermal lag, τ ≈ 45 s)
 *    Q_transfer = U · A_contact · (T_plate - T_vessel_bottom)
 * 2. Bunsen Burner:
 *    Dual mode: Premixed blue flame (air vent open, ~1500 °C) vs luminous yellow (air vent closed, ~850 °C).
 *    Local concentrated heat flux Q_burner ≈ 300 - 600 W.
 * 3. Ice Bath:
 *    Constant 273.15 K boundary condition, absorbs heat via ice fusion L_f = 334 kJ/kg.
 * 
 * Units: SI internally (K, W, s, W/m²K, m²)
 */

export type HeaterType = 'none' | 'hotplate' | 'bunsen' | 'icebath';

export interface HeaterState {
  type: HeaterType;
  isOn: boolean;
  setpointTempK: number;
  currentTempK: number;
  powerW: number;
  isAirHoleOpen: boolean; // For Bunsen burner
}

export class HeaterDevice {
  public type: HeaterType = 'none';
  public isOn: boolean = false;
  public setpointTempK: number = 293.15;
  public currentTempK: number = 293.15;
  public isAirHoleOpen: boolean = true; // Blue flame by default

  private hotplateTau: number = 45.0; // 45 s thermal time constant
  private uOverall: number = 450.0;   // Heat transfer coefficient W/(m² K)

  public setType(type: HeaterType): void {
    this.type = type;
    if (type === 'icebath') {
      this.currentTempK = 273.15;
      this.setpointTempK = 273.15;
      this.isOn = true;
    } else if (type === 'bunsen') {
      this.currentTempK = 293.15;
    }
  }

  public setPower(on: boolean, setpointC: number = 150): void {
    this.isOn = on;
    this.setpointTempK = setpointC + 273.15;
  }

  /**
   * Update heater device temperature and calculate net heat transferred to vessel bottom (W)
   */
  public step(dt: number, vesselBottomTempK: number, contactAreaM2: number = 0.005): number {
    if (dt <= 0 || !this.isOn || this.type === 'none') {
      // Passive cooling back to ambient (293.15 K)
      this.currentTempK += (293.15 - this.currentTempK) * Math.min(1.0, 0.05 * dt);
      return 0;
    }

    if (this.type === 'hotplate') {
      // First-order thermal lag towards setpoint
      this.currentTempK += ((this.setpointTempK - this.currentTempK) / this.hotplateTau) * dt;
      const deltaT = Math.max(0, this.currentTempK - vesselBottomTempK);
      return this.uOverall * contactAreaM2 * deltaT;
    }

    if (this.type === 'bunsen') {
      // Immediate flame power delivery
      const maxPower = this.isAirHoleOpen ? 550.0 : 350.0;
      this.currentTempK = this.isAirHoleOpen ? 1773.15 : 1123.15; // 1500°C blue / 850°C yellow
      const deltaT = Math.max(0, this.currentTempK - vesselBottomTempK);
      const transferredW = Math.min(maxPower, 200.0 + deltaT * 0.2);
      return transferredW;
    }

    if (this.type === 'icebath') {
      this.currentTempK = 273.15;
      // Cooling is negative heat into vessel
      const deltaT = vesselBottomTempK - 273.15;
      return -this.uOverall * contactAreaM2 * Math.max(0, deltaT);
    }

    return 0;
  }
}

sim\\particles.ts:
/**
 * particles.ts - High-performance Structure-of-Arrays (SoA) particle system with free-list pool.
 * 
 * Design Constraints:
 * 1. Zero heap allocations in the hot per-frame simulation loop.
 * 2. Continuous Float32Array buffers for cache locality and WebGL instanced buffer streaming.
 * 3. Particle types: BUBBLE, PRECIPITATE, DROPLET, STEAM, SPARK.
 * 4. Spatial hash grid for O(1) local neighbor queries and coalescence.
 * 
 * Units: SI internally (m, m/s, s, kg/m³)
 */

export const enum ParticleType {
  BUBBLE = 0,
  PRECIPITATE = 1,
  DROPLET = 2,
  STEAM = 3,
  SPARK = 4,
}

export interface ParticleSpawnParams {
  type: ParticleType;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  radius: number;
  maxAge: number;
  weight?: number;
  r?: number;
  g?: number;
  b?: number;
  a?: number;
}

export class ParticleSystem {
  public readonly capacity: number;
  public activeCount: number = 0;

  // Structure-of-Arrays (SoA) flat buffers
  public x: Float32Array;
  public y: Float32Array;
  public z: Float32Array;
  public vx: Float32Array;
  public vy: Float32Array;
  public vz: Float32Array;
  public radius: Float32Array;
  public age: Float32Array;
  public maxAge: Float32Array;
  public type: Uint8Array;
  public weight: Float32Array;
  public r: Float32Array;
  public g: Float32Array;
  public b: Float32Array;
  public a: Float32Array;
  public phase: Float32Array; // Angular phase for wobble / flutter

  // Free-list indices pool
  private freeList: Int32Array;
  private freeCount: number;

  constructor(capacity: number = 20000) {
    this.capacity = capacity;
    this.x = new Float32Array(capacity);
    this.y = new Float32Array(capacity);
    this.z = new Float32Array(capacity);
    this.vx = new Float32Array(capacity);
    this.vy = new Float32Array(capacity);
    this.vz = new Float32Array(capacity);
    this.radius = new Float32Array(capacity);
    this.age = new Float32Array(capacity);
    this.maxAge = new Float32Array(capacity);
    this.type = new Uint8Array(capacity);
    this.weight = new Float32Array(capacity);
    this.r = new Float32Array(capacity);
    this.g = new Float32Array(capacity);
    this.b = new Float32Array(capacity);
    this.a = new Float32Array(capacity);
    this.phase = new Float32Array(capacity);

    this.freeList = new Int32Array(capacity);
    for (let i = 0; i < capacity; i++) {
      this.freeList[i] = i;
    }
    this.freeCount = capacity;
  }

  /**
   * Spawn a new particle from free list. Returns particle index or -1 if capacity full.
   */
  public spawn(params: ParticleSpawnParams): number {
    if (this.freeCount <= 0) return -1;

    this.freeCount--;
    const idx = this.freeList[this.freeCount];

    this.x[idx] = params.x;
    this.y[idx] = params.y;
    this.z[idx] = params.z;
    this.vx[idx] = params.vx;
    this.vy[idx] = params.vy;
    this.vz[idx] = params.vz;
    this.radius[idx] = params.radius;
    this.age[idx] = 0;
    this.maxAge[idx] = params.maxAge;
    this.type[idx] = params.type;
    this.weight[idx] = params.weight ?? 1.0;
    this.r[idx] = params.r ?? 1.0;
    this.g[idx] = params.g ?? 1.0;
    this.b[idx] = params.b ?? 1.0;
    this.a[idx] = params.a ?? 1.0;
    this.phase[idx] = Math.random() * Math.PI * 2;

    this.activeCount++;
    return idx;
  }

  /**
   * Recycle particle at index back into free pool
   */
  public kill(idx: number): void {
    if (this.freeCount >= this.capacity) return;
    this.maxAge[idx] = 0;
    this.freeList[this.freeCount] = idx;
    this.freeCount++;
    this.activeCount--;
  }

  /**
   * Clear all active particles
   */
  public reset(): void {
    this.freeCount = this.capacity;
    for (let i = 0; i < this.capacity; i++) {
      this.freeList[i] = i;
      this.maxAge[i] = 0;
    }
    this.activeCount = 0;
  }

  /**
   * Compact integration pass over active particles with lifecycle updates
   */
  public integrate(dt: number, onDeath?: (idx: number, type: ParticleType) => void): void {
    if (dt <= 0 || this.activeCount <= 0) return;

    for (let i = 0; i < this.capacity; i++) {
      if (this.age[i] >= this.maxAge[i]) continue;

      this.age[i] += dt;
      if (this.age[i] >= this.maxAge[i]) {
        if (onDeath) onDeath(i, this.type[i]);
        this.kill(i);
        continue;
      }

      // Kinematic update
      this.x[i] += this.vx[i] * dt;
      this.y[i] += this.vy[i] * dt;
      this.z[i] += this.vz[i] * dt;
    }
  }
}

sim\\pour.ts:
/**
 * pour.ts - Hydraulic pouring weir laws, ballistic stream ribbon,
 * Rayleigh-Plateau droplet breakup, Tate's law dropper, and air entrainment.
 * 
 * Physical Model:
 * 1. Weir Law Flow Rate (Poleni / Francis formula for open spout):
 *    Q = (2/3) · C_d · w · sqrt(2g) · H^(3/2)
 *    C_d ≈ 0.62, w = lip width (m), H = hydraulic head above lip (m)
 * 2. Ballistic Stream Parabola:
 *    v₀ ≈ 0.8 · sqrt(2 g H)
 *    r(t) = r₀ + v₀ t + 0.5 g t²
 * 3. Continuity Stream Thinning:
 *    A(s) = Q / v(s)  ->  radius r_stream(s) = sqrt(Q / (π v(s)))
 * 4. Rayleigh-Plateau Breakup:
 *    t_breakup ≈ 2.9 · sqrt(ρ · r³ / σ)
 *    L_breakup = v · t_breakup. Beyond L_breakup, jet breaks into discrete droplets.
 * 5. Tate's Law Dropper:
 *    V_drop = (2 π r_tip · σ / (ρ g)) · 0.68  (~0.05 mL for water)
 * 6. Plunging Jet Air Entrainment:
 *    If impact speed v > 1.0 m/s, entrain small air bubbles into receiving vessel.
 * 
 * Units: SI internally (m, m/s, m³/s, s, N/m, kg/m³)
 */

import { GRAVITY } from '../core/units.js';

export interface PourStreamPoint {
  x: number;
  y: number;
  z: number;
  radius: number;
  speed: number;
  isDroplet: boolean;
}

export class PouringSimulator {
  public cd: number = 0.62;
  public spoutWidthM: number = 0.012; // 12 mm spout width
  public surfaceTension: number = 0.0728; // N/m
  public density: number = 1000.0; // kg/m³

  /**
   * Compute volumetric flow rate Q (m³/s) from liquid head H above lip
   */
  public computeWeirFlow(headAboveLipM: number): number {
    if (headAboveLipM <= 0) return 0;
    // Q = (2/3) · Cd · w · sqrt(2g) · H^(3/2)
    const q = (2.0 / 3.0) * this.cd * this.spoutWidthM * Math.sqrt(2.0 * GRAVITY) * Math.pow(headAboveLipM, 1.5);
    return Math.max(0, q);
  }

  /**
   * Compute Tate's law single droplet volume (m³)
   */
  public computeDropletVolume(tipRadiusM: number = 0.0015): number {
    // V_drop = (2 π r_tip σ / (ρ g)) * Harkins-Brown correction (0.68)
    const vDrop = ((2.0 * Math.PI * tipRadiusM * this.surfaceTension) / (this.density * GRAVITY)) * 0.68;
    return Math.max(1e-8, vDrop); // ~0.05 mL (5e-8 m³)
  }

  /**
   * Generate ballistic stream trajectory points with Rayleigh-Plateau breakup
   */
  public generateStreamTrajectory(
    startX: number,
    startY: number,
    startZ: number,
    dirX: number,
    dirZ: number,
    flowRateQ: number,
    targetFloorY: number,
    numSamples: number = 16
  ): PourStreamPoint[] {
    const points: PourStreamPoint[] = [];
    if (flowRateQ <= 1e-9) return points;

    // Initial exit velocity
    const v0 = Math.max(0.2, Math.sqrt(2.0 * GRAVITY * 0.01)); // ~0.44 m/s
    const vx0 = dirX * v0;
    const vz0 = dirZ * v0;
    let vy0 = 0;

    // Estimate initial stream radius
    const r0 = Math.sqrt(flowRateQ / (Math.PI * v0));
    // Rayleigh breakup time: tb ≈ 2.9 * sqrt(ρ r0³ / σ)
    const tBreakup = 2.9 * Math.sqrt((this.density * Math.pow(r0, 3)) / this.surfaceTension);

    let t = 0;
    const dt = 0.02; // 20 ms trajectory steps

    for (let i = 0; i < numSamples; i++) {
      const px = startX + vx0 * t;
      const py = startY + vy0 * t - 0.5 * GRAVITY * t * t;
      const pz = startZ + vz0 * t;

      if (py < targetFloorY) {
        // Impact
        points.push({
          x: px,
          y: targetFloorY,
          z: pz,
          radius: r0,
          speed: Math.sqrt(vx0 * vx0 + (vy0 - GRAVITY * t) ** 2 + vz0 * vz0),
          isDroplet: t > tBreakup,
        });
        break;
      }

      const currentVy = vy0 - GRAVITY * t;
      const speed = Math.sqrt(vx0 * vx0 + currentVy * currentVy + vz0 * vz0);
      const area = flowRateQ / Math.max(0.1, speed);
      const rStream = Math.sqrt(area / Math.PI);

      points.push({
        x: px,
        y: py,
        z: pz,
        radius: rStream,
        speed,
        isDroplet: t > tBreakup,
      });

      t += dt;
    }

    return points;
  }
}

sim\\precipitation.ts:
/**
 * precipitation.ts - Classical nucleation, crystal growth, morphology presets,
 * hindered settling (Richardson-Zaki), sediment bed with angle of repose, and resuspension.
 * 
 * Physical Model:
 * 1. Classical Nucleation Rate:
 *    J(S) = A_n · exp(-B_n / ln²(S))  (nuclei / (m³ s))
 *    S = (Q / K_sp)^(1/ν)  (supersaturation ratio)
 * 2. Particle Growth:
 *    dr̄/dt = k_g · (S - 1)^g
 * 3. Stokes & Richardson-Zaki Hindered Settling:
 *    v_s = (2/9) · (ρ_p - ρ_l) · g · r² / μ
 *    v_hindered = v_s · (1 - φ)^4.65
 * 4. Sediment Bed & Angle of Repose:
 *    Deposition height-field b(x, z) at bottom of vessel.
 *    Thermal erosion algorithm moves mass when local slope > tan(φ_repose) (~30°).
 * 5. Resuspension (Shields Criterion):
 *    Bottom fluid shear stress τ = μ · (∂u/∂y). If τ > τ_crit, bed resuspends.
 * 6. PbI2 "Golden Rain" Thermal Recrystallization:
 *    Temperature-dependent solubility Cs(T) causes dissolution when hot (>80°C)
 *    and nucleation of glittering hexagonal plates upon cooling.
 * 
 * Units: SI internally (m, kg, s, K, mol/m³, Pa s)
 */

import { GRAVITY } from '../core/units.js';
import { ParticleSystem, ParticleType } from './particles.js';

export type PrecipitateMorphology =
  | 'curdy'
  | 'fine_crystalline'
  | 'gelatinous'
  | 'flocculent'
  | 'crystalline_dense'
  | 'colloidal';

export interface MorphologyPreset {
  morphology: PrecipitateMorphology;
  particleRadiusMinM: number;
  particleRadiusMaxM: number;
  densityKgPerM3: number;
  bedPorosity: number;
  settlingRateMultiplier: number;
  colorR: number;
  colorG: number;
  colorB: number;
  alpha: number;
}

export const PRECIPITATE_PRESETS: Record<PrecipitateMorphology, MorphologyPreset> = {
  curdy: {
    morphology: 'curdy',
    particleRadiusMinM: 2e-6,
    particleRadiusMaxM: 50e-6,
    densityKgPerM3: 5560, // AgCl
    bedPorosity: 0.85,
    settlingRateMultiplier: 1.0,
    colorR: 0.96,
    colorG: 0.96,
    colorB: 0.94,
    alpha: 0.9,
  },
  fine_crystalline: {
    morphology: 'fine_crystalline',
    particleRadiusMinM: 0.2e-6,
    particleRadiusMaxM: 2e-6,
    densityKgPerM3: 4500, // BaSO4
    bedPorosity: 0.65,
    settlingRateMultiplier: 0.15,
    colorR: 0.98,
    colorG: 0.98,
    colorB: 0.98,
    alpha: 0.85,
  },
  gelatinous: {
    morphology: 'gelatinous',
    particleRadiusMinM: 0.1e-6,
    particleRadiusMaxM: 10e-6,
    densityKgPerM3: 2400, // Cu(OH)2, Al(OH)3
    bedPorosity: 0.95,
    settlingRateMultiplier: 0.3,
    colorR: 0.45,
    colorG: 0.75,
    colorB: 0.95,
    alpha: 0.7,
  },
  flocculent: {
    morphology: 'flocculent',
    particleRadiusMinM: 5e-6,
    particleRadiusMaxM: 150e-6,
    densityKgPerM3: 3400, // Fe(OH)3 rust
    bedPorosity: 0.9,
    settlingRateMultiplier: 0.8,
    colorR: 0.75,
    colorG: 0.35,
    colorB: 0.15,
    alpha: 0.92,
  },
  crystalline_dense: {
    morphology: 'crystalline_dense',
    particleRadiusMinM: 10e-6,
    particleRadiusMaxM: 120e-6,
    densityKgPerM3: 6160, // PbI2 golden rain
    bedPorosity: 0.55,
    settlingRateMultiplier: 2.2,
    colorR: 0.98,
    colorG: 0.85,
    colorB: 0.12,
    alpha: 0.95,
  },
  colloidal: {
    morphology: 'colloidal',
    particleRadiusMinM: 0.1e-6,
    particleRadiusMaxM: 0.8e-6,
    densityKgPerM3: 2070, // Colloidal Sulfur
    bedPorosity: 0.7,
    settlingRateMultiplier: 0.02,
    colorR: 0.95,
    colorG: 0.92,
    colorB: 0.65,
    alpha: 0.75,
  },
};

export class PrecipitationPipeline {
  public preset: MorphologyPreset;
  public suspendedMoles: number = 0;
  public sedimentMoles: number = 0;

  // Bed height field on vessel floor (grid 32x32)
  public readonly bedRes: number = 32;
  public bedHeight: Float32Array;
  public vesselRadius: number;

  constructor(morphology: PrecipitateMorphology = 'curdy', vesselRadius: number = 0.04) {
    this.preset = PRECIPITATE_PRESETS[morphology] ?? PRECIPITATE_PRESETS.curdy;
    this.vesselRadius = vesselRadius;
    this.bedHeight = new Float32Array(this.bedRes * this.bedRes);
  }

  /**
   * Set active morphology preset
   */
  public setMorphology(morphology: PrecipitateMorphology): void {
    if (PRECIPITATE_PRESETS[morphology]) {
      this.preset = PRECIPITATE_PRESETS[morphology];
    }
  }

  /**
   * Nucleate precipitate when supersaturation S > 1.0
   * @param supersaturation S = (Q / Ksp)^(1/ν)
   * @param molesExcess Total moles available above saturation
   * @param dt Time step (s)
   */
  public nucleate(supersaturation: number, molesExcess: number, dt: number): number {
    if (supersaturation <= 1.0001 || molesExcess <= 0) return 0;

    // Classical nucleation rate J = An * exp(-Bn / ln²(S))
    const lnS = Math.log(supersaturation);
    const bn = 1.8; // Tuned for realistic laboratory onset
    const jRate = Math.min(1.0, Math.exp(-bn / (lnS * lnS)));

    // Approach equilibrium with kinetic rate
    const molesToPrecip = Math.min(molesExcess, molesExcess * (1.0 - Math.exp(-jRate * 8.0 * dt)));
    this.suspendedMoles += molesToPrecip;
    return molesToPrecip;
  }

  /**
   * Update sedimentation, bed accumulation, and shear resuspension
   */
  public update(
    dt: number,
    particles: ParticleSystem,
    liquidHeightM: number,
    bottomShearStressPa: number,
    stirrerSpeedRadS: number
  ): void {
    if (dt <= 0) return;

    const rhoP = this.preset.densityKgPerM3;
    const rhoL = 1000.0;
    const mu = 1.0e-3; // Water dynamic viscosity (Pa s)
    const rMean = (this.preset.particleRadiusMinM + this.preset.particleRadiusMaxM) * 0.5;

    // 1. Single-particle Stokes velocity: v_s = (2/9) * (ρ_p - ρ_l) * g * r² / μ
    const vStokes = (2.0 / 9.0) * (rhoP - rhoL) * GRAVITY * (rMean * rMean) / mu;

    // Volume fraction φ of suspended solids
    const solidVolume = this.suspendedMoles * 0.00003; // Approx 30 mL/mol
    const liquidVolume = Math.PI * this.vesselRadius * this.vesselRadius * liquidHeightM;
    const phi = Math.min(0.5, solidVolume / Math.max(1e-6, liquidVolume));

    // Richardson-Zaki hindered settling: v = v_s * (1 - φ)^4.65
    const vHindered = vStokes * Math.pow(Math.max(0, 1.0 - phi), 4.65) * this.preset.settlingRateMultiplier;

    // 2. Settle suspended moles into sediment bed
    if (this.suspendedMoles > 0 && liquidHeightM > 0) {
      const settleFraction = Math.min(1.0, (vHindered * dt) / Math.max(0.01, liquidHeightM));
      const molesSettled = this.suspendedMoles * settleFraction;
      this.suspendedMoles -= molesSettled;
      this.sedimentMoles += molesSettled;

      // Deposit into center of bed height-field
      this.depositToBed(molesSettled);
    }

    // 3. Angle of repose relaxation on sediment bed (thermal erosion)
    this.relaxBedAngleOfRepose();

    // 4. Resuspension from bottom shear stress (Shields criterion)
    const tauCrit = 0.04 * (rhoP - rhoL) * GRAVITY * (2.0 * rMean); // Critical Shields shear (Pa)
    const activeShear = bottomShearStressPa + stirrerSpeedRadS * 0.02;

    if (activeShear > tauCrit && this.sedimentMoles > 0) {
      const resuspendRate = Math.min(0.5, (activeShear - tauCrit) / (tauCrit + 1e-4) * 2.0 * dt);
      const molesResuspended = this.sedimentMoles * resuspendRate;
      this.sedimentMoles -= molesResuspended;
      this.suspendedMoles += molesResuspended;
      this.erodeBed(resuspendRate);
    }

    // 5. Update render particles for visible glittering flocs / curds
    for (let i = 0; i < particles.capacity; i++) {
      if (particles.age[i] >= particles.maxAge[i] || particles.type[i] !== ParticleType.PRECIPITATE) {
        continue;
      }

      // Settling motion
      particles.vy[i] = -vHindered;

      // Bottom impact
      if (particles.y[i] <= 0.002) {
        particles.kill(i);
      }
    }
  }

  /**
   * Deposit sediment moles onto the bottom height-field grid
   */
  private depositToBed(moles: number): void {
    const molarVolumeM3 = 0.00003; // ~30 cm³/mol
    const totalVolumeM3 = moles * molarVolumeM3 / (1.0 - this.preset.bedPorosity);
    const cellArea = (2.0 * this.vesselRadius / this.bedRes) ** 2;
    const heightIncrement = totalVolumeM3 / (Math.PI * this.vesselRadius * this.vesselRadius);

    const mid = Math.floor(this.bedRes / 2);
    for (let j = 0; j < this.bedRes; j++) {
      for (let i = 0; i < this.bedRes; i++) {
        const di = i - mid;
        const dj = j - mid;
        const rNorm2 = (di * di + dj * dj) / (mid * mid);
        if (rNorm2 <= 1.0) {
          const factor = Math.exp(-rNorm2 * 2.0);
          this.bedHeight[j * this.bedRes + i] += heightIncrement * factor;
        }
      }
    }
  }

  /**
   * Erode sediment bed proportionally during resuspension
   */
  private erodeBed(fraction: number): void {
    for (let i = 0; i < this.bedHeight.length; i++) {
      this.bedHeight[i] = Math.max(0, this.bedHeight[i] * (1.0 - fraction));
    }
  }

  /**
   * Angle of repose relaxation: move material downhill when slope exceeds tan(30°) ≈ 0.577
   */
  private relaxBedAngleOfRepose(): void {
    const N = this.bedRes;
    const dx = (2.0 * this.vesselRadius) / (N - 1);
    const maxSlope = Math.tan(30.0 * Math.PI / 180.0); // 30° angle of repose

    for (let j = 1; j < N - 1; j++) {
      const row = j * N;
      for (let i = 1; i < N - 1; i++) {
        const idx = row + i;
        const hCenter = this.bedHeight[idx];

        // Check 4 neighbors
        const neighbors = [idx - 1, idx + 1, idx - N, idx + N];
        for (const nIdx of neighbors) {
          const diff = hCenter - this.bedHeight[nIdx];
          const slope = diff / dx;
          if (slope > maxSlope) {
            const shift = (slope - maxSlope) * dx * 0.25;
            this.bedHeight[idx] -= shift;
            this.bedHeight[nIdx] += shift;
          }
        }
      }
    }
  }
}

