    rotateVessel: (id, angleDeltaRad = Math.PI / 4) => {
      set(s => {
        if (!s.vessels[id]) return s;
        const updated = {
          ...s.vessels,
          [id]: { ...s.vessels[id], rotationY: (s.vessels[id].rotationY + angleDeltaRad) % (Math.PI * 2) }
        };
        debounceSaveLocalState(updated, s.burners);
        return { vessels: updated };
      });
