        debounceSaveLocalState(updated, s.burners);
        return { vessels: updated };
      });
    },

    sealVessel: (id) => {
      const v = get().vessels[id];
      if (!v) return;
      labSound.playTap();
      set(s => {
        const updated = {
          ...s.vessels,
          [id]: { ...v, isSealed: !v.isSealed, internalPressure_atm: v.isSealed ? 1.0 : (v.internalPressure_atm || 1.0) }
        };
