        dpr={[Math.min(1, qualitySettings.dprMax), qualitySettings.dprMax]}
        camera={{ position: [0, 5.2, 12], fov: 45, near: 0.1, far: 120 }}
        gl={{
          antialias: false,
          powerPreference: 'high-performance',
          toneMapping: THREE.NoToneMapping,
          stencil: false,
        }}
        onCreated={({ gl }) => {
          gl.localClippingEnabled = true;
        }}
