import { BoilingStage, EvaporationRegime, MatterPhase } from '../core/SimulationTypes';
import { DEFAULT_SIMULATION_CONFIG } from '../core/SimulationConfig';

/**
 * Determines current boiling stage from thermodynamic state
 */
export function determineBoilingStage(
  temp_c: number,
  boilingPoint_c: number = DEFAULT_SIMULATION_CONFIG.waterBoilingPoint_c,
  heatPower_W: number = 0
): { stage: BoilingStage; intensity: number } {
  const onset = boilingPoint_c - 5.5; // ~94.5°C
  const microbubble = boilingPoint_c - 20.0; // ~80.0°C
  const rolling = boilingPoint_c - 1.8; // ~98.2°C

  if (temp_c >= rolling || (temp_c >= onset && heatPower_W > 15)) {
    const intensity = Math.min(1.0, 0.65 + Math.min(0.35, (temp_c - rolling) / 2.0));
    return { stage: 'INTENSE_ROLLING_BOIL', intensity };
  }

  if (temp_c >= onset) {
    const intensity = Math.min(0.65, 0.25 + ((temp_c - onset) / (rolling - onset)) * 0.4);
    return { stage: 'ACTIVE_BOIL', intensity };
  }

  if (temp_c >= onset - 1.5) {
    return { stage: 'BOILING_ONSET', intensity: 0.2 };
  }

  if (temp_c >= microbubble) {
    const frac = (temp_c - microbubble) / (onset - microbubble);
    return { stage: 'MICROBUBBLE_NUCLEATION', intensity: frac * 0.15 };
  }

  if (temp_c >= DEFAULT_SIMULATION_CONFIG.convectionOnsetTemp_c || heatPower_W > 5) {
    return { stage: 'WARMING_CONVECTION', intensity: 0.0 };
  }

  return { stage: 'COLD_STABLE', intensity: 0.0 };
}

/**
 * Determines evaporation regime from temperature, exposed surface area, and airflow
 */
export function determineEvaporationRegime(
  temp_c: number,
  surfaceArea_cm2: number,
  isBoiling: boolean
): { regime: EvaporationRegime; rate_ml_s: number } {
  if (isBoiling) {
    const boilRate = 0.08 + (temp_c >= 99 ? 0.12 : 0.04) * (surfaceArea_cm2 / 25.0);
    return { regime: 'VAPOR_PLUME', rate_ml_s: boilRate };
  }

  // Dalton/Antoine surface vaporization rate
  // Vapor pressure P_v(T) = exp(A - B / (T + C))
  const T = Math.max(15, Math.min(100, temp_c));
  const normalizedTempFactor = Math.pow((T - 15) / 85.0, 2.6); // Exponential climb as T approaches 100°C
  const areaFactor = Math.max(0.2, surfaceArea_cm2 / 20.0); // Baseline 20 cm2 ~ 5 cm diameter beaker

  const baseRate = 0.00015 + normalizedTempFactor * 0.035 * areaFactor;

  if (T >= 85) {
    return { regime: 'HIGH_THERMAL_EVAPORATION', rate_ml_s: baseRate };
  }
  if (T >= 60) {
    return { regime: 'MODERATE_EVAPORATION', rate_ml_s: baseRate };
  }
  if (T >= 35) {
    return { regime: 'LOW_EVAPORATION', rate_ml_s: baseRate };
  }

  return { regime: 'AMBIENT_DORMANT', rate_ml_s: baseRate * 0.2 };
}

/**
 * Computes fluid viscosity as a function of temperature and solute concentration
 * Water viscosity decreases exponentially with temperature (0.0018 Pa·s at 0°C -> 0.00028 Pa·s at 100°C)
 */
export function computeFluidViscosity(temp_c: number, soluteConcentration_M: number = 0): number {
  // Andrade equation approximation for water
  const T_kelvin = temp_c + 273.15;
  const baseWaterViscosity_mPa_s = 0.02414 * Math.pow(10, 247.8 / (T_kelvin - 140)); // mPa*s
  // Viscosity increases with solute concentration (Jones-Dole equation approx)
  const concentrationMultiplier = 1.0 + 0.08 * soluteConcentration_M;
  return baseWaterViscosity_mPa_s * concentrationMultiplier;
}

/**
 * Computes fluid density (water thermal expansion + dissolved solute mass)
 */
export function computeFluidDensity(temp_c: number, soluteMass_g: number, totalVolume_ml: number): number {
  if (totalVolume_ml <= 0.001) return 1.0;
  // Water thermal density expansion: ~1.0 g/mL at 4°C, ~0.958 g/mL at 100°C
  const waterDensity = 1.0 - Math.pow(Math.max(0, temp_c - 4) / 100, 2) * 0.043;
  const totalMass_g = (totalVolume_ml * waterDensity) + soluteMass_g;
  return totalMass_g / totalVolume_ml;
}

/**
 * SOLUBILITY AND SUPERSATURATION ENGINE
 * Calculates temperature-dependent solubility limits, ion products,
 * supersaturation states, and recrystallization dynamics (e.g. PbI2 Golden Rain).
 */

export interface SolubilityCurve {
  formula: string;
  name: string;
  // Solubility in g per 100 mL of water as function of temperature (°C)
  // S(T) = s0 + s1 * T + s2 * T^2
  s0: number;
  s1: number;
  s2: number;
  // Ksp at 25°C
  ksp_25: number;
  // Enthalpy of dissolution kJ/mol (positive = endothermic, dissolves more when heated)
  deltaH_dissolution_kJ: number;
}

export const SOLUBILITY_DATABASE: Record<string, SolubilityCurve> = {
  // PbI2: Low solubility at room temp (~0.076 g/100mL), but dramatically dissolves in boiling water (~0.43 g/100mL)!
  'PbI2': {
    formula: 'PbI2',
    name: 'Lead(II) Iodide',
    s0: 0.044,
    s1: 0.0016,
    s2: 0.000022,
    ksp_25: 9.8e-9,
    deltaH_dissolution_kJ: 46.5
  },
  // BaSO4: Extremely insoluble (~0.00024 g/100mL at 25°C), stays insoluble even when heated
  'BaSO4': {
    formula: 'BaSO4',
    name: 'Barium Sulfate',
    s0: 0.00020,
    s1: 0.0000018,
    s2: 0,
    ksp_25: 1.1e-10,
    deltaH_dissolution_kJ: 26.0
  },
  // AgCl: Extremely insoluble (~0.00019 g/100mL at 25°C)
  'AgCl': {
    formula: 'AgCl',
    name: 'Silver Chloride',
    s0: 0.00015,
    s1: 0.0000018,
    s2: 0,
    ksp_25: 1.8e-10,
    deltaH_dissolution_kJ: 65.5
  },
  // Cu(OH)2: Insoluble, decomposes thermally above 60°C to CuO
  'Cu(OH)2': {
    formula: 'Cu(OH)2',
    name: 'Copper(II) Hydroxide',
    s0: 0.000001,
    s1: 0,
    s2: 0,
    ksp_25: 2.2e-20,
    deltaH_dissolution_kJ: 10.0
  },
  // NaCl: Soluble table salt (~36 g / 100mL), very flat solubility curve
  'NaCl': {
    formula: 'NaCl',
    name: 'Sodium Chloride',
    s0: 35.7,
    s1: 0.025,
    s2: 0.0001,
    ksp_25: 37.0,
    deltaH_dissolution_kJ: 3.88
  },
  // CuSO4: Soluble (~20 g / 100mL at 20°C, ~75 g / 100mL at 100°C)
  'CuSO4': {
    formula: 'CuSO4',
    name: 'Copper(II) Sulfate',
    s0: 14.3,
    s1: 0.28,
    s2: 0.0033,
    ksp_25: 1.5,
    deltaH_dissolution_kJ: 11.7
  }
};

/**
 * Returns maximum solubility in grams per 100 mL of solvent at temperature T (°C)
 */
export function getSolubilityLimit_g_100ml(formula: string, temp_c: number): number {
  const curve = SOLUBILITY_DATABASE[formula];
  if (!curve) return 999.0; // Assume freely soluble if not listed
  const t = Math.max(0, Math.min(100, temp_c));
  return Math.max(0.0000001, curve.s0 + curve.s1 * t + curve.s2 * t * t);
}

/**
 * Returns solubility product Ksp at temperature T (°C) using van 't Hoff equation
 */
export function getSolubilityProduct(formula: string, temp_c: number = 25): number {
  const curve = SOLUBILITY_DATABASE[formula];
  if (!curve) return 1.0;
  const T1 = 298.15;
  const T2 = (temp_c ?? 25) + 273.15;
  const R = 8.314;
  const dH_J = (curve.deltaH_dissolution_kJ || 0) * 1000;
  const lnRatio = -(dH_J / R) * (1 / T2 - 1 / T1);
  return curve.ksp_25 * Math.exp(lnRatio);
}

export interface SaturationCheckResult {
  isSupersaturated: boolean;
  saturationRatio: number;      // > 1.0 means precipitate will form/grow
  dissolvedMass_g: number;
  excessPrecipitate_g: number;  // mass that must crystallize out
  saturationLimit_g: number;
}

/**
 * Evaluates whether a solute has exceeded its solubility limit in a given solvent volume
 */
export function checkSaturation(
  formula: string,
  soluteMass_g: number,
  solventVolume_ml: number,
  temp_c: number
): SaturationCheckResult {
  if (solventVolume_ml <= 0.01) {
    return {
      isSupersaturated: soluteMass_g > 0,
      saturationRatio: soluteMass_g > 0 ? 999.0 : 0,
      dissolvedMass_g: 0,
      excessPrecipitate_g: soluteMass_g,
      saturationLimit_g: 0
    };
  }

  const limit_g_per_100ml = getSolubilityLimit_g_100ml(formula, temp_c);
  const maxDissolvable_g = (limit_g_per_100ml / 100.0) * solventVolume_ml;
  const saturationRatio = soluteMass_g / Math.max(0.000001, maxDissolvable_g);

  const isSupersaturated = saturationRatio > 1.0;
  const dissolvedMass_g = Math.min(soluteMass_g, maxDissolvable_g);
  const excessPrecipitate_g = Math.max(0, soluteMass_g - maxDissolvable_g);

  return {
    isSupersaturated,
    saturationRatio,
    dissolvedMass_g,
    excessPrecipitate_g,
    saturationLimit_g: maxDissolvable_g
  };
}

