    const depth = 0.18;
    for (let i = 0; i <= samples; i++) {
      const t = i / samples;
      const r = t * maxR;
      const y = -depth * (1.0 - t * t);
      outerPoints.push(new THREE.Vector2(r, y));
    }
    outerPoints.push(new THREE.Vector2(maxR + 0.025, 0.02));

    for (let i = 0; i <= samples; i++) {
      const t = i / samples;
      const r = t * (maxR - 0.02);
      const y = -depth * (1.0 - t * t) + 0.025;
      innerPoints.push(new THREE.Vector2(r, y));
