      ? (vessel.boilingIntensity || (isTempBoiling ? Math.min(1.0, (vessel.temperature_c - 95) / 5) : 0.7))
      : 0.0;
    if (simMgr && simMgr.boilingSystem.bubbles.length > 0) {
