          <meshStandardMaterial color="#334155" roughness={0.6} metalness={0.6} />
        </mesh>
        {/* Clamp Adjusting Screws */}
        <mesh position={[-0.45, 0.12, 0]} rotation={[0, 0, 0]}>
          <cylinderGeometry args={[0.03, 0.03, 0.15, 12]} />
