  mount(ctx, p) {
    return {
      atom: 'stokesSedimentation',
      instanceId: `ss_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
      alive: true,
      custom: {
        ...p,
        elapsed: 0,
        settlingProgress: 0,
        currentBedHeight_mm: 0,
        targetBedHeight_mm: p.bedHeight_mm ?? 6.0
      }
    };
  },
  update(h, dt, s) {
    if (!h.alive) return;
    h.custom.elapsed += dt;
    const r_um = h.custom.stokesRadius_um ?? 4.5;
