  },
  budget: { particles: 48, shaderCost: 1 },
  anchorsAllowed: ['rim', 'surface'],
  mount(ctx, p) {
    return {
      atom: 'thermalSteam',
      instanceId: `ts_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
      alive: true,
      custom: {
        ...p,
        elapsed: 0,
        steamDensity: p.steamDensity ?? 1.0,
        temperature_c: p.temperature_c ?? 75,
        steamVigor: 0
      }
    };
  },
  update(h, dt, s) {
    if (!h.alive) return;
    h.custom.elapsed += dt;
